  stations = {
    ["01-1"] = {name="Tal der Prüfungen", tips={{k="交通", text="Kommen Sie aus einer anderen Startzone? Folgen Sie der Straße nach Süden durch Durotar. Geben Sie Das Tal der Prüfungen von Osten ein und finden Sie Kaltunk. Sieh oben bei den Reisehinweisen nach."}, {k="取捨", text="Erledige die Quests Verlorene Waffen, Faule Peons und beide Koven der Burning Blade. Gruppieren Sie die Ziele in zwei Schleifen."}, {k="取捨", text="Schließe die Wichtel-Quest (Üble Familiare oder Üble Familiare) ab und akzeptiere dann Medaillon der Burning Blade von Zureetha Fargaze. Nur Hexenmeister.", s={{"Schließe die Wichtel-Quest (Üble Familiare oder Üble Familiare) ab und akzeptiere dann Medaillon der Burning Blade von Zureetha Fargaze. Nur Hexenmeister.", {class={"WARLOCK"}}}}}, {k="提醒", text="Unter Level 6? Töte Scheckiger Eber, Skorpidarbeiter oder Übler Familiar auf dem Weg zu Sen'jin.", s={{"Unter Level 6?"}, {"Töte Scheckiger Eber, Skorpidarbeiter oder Übler Familiar auf dem Weg zu Sen'jin"}}}}, danger={[1]="Die Biegung in Koven der Burning Blade kann mehrere Kobolde gleichzeitig ziehen. Räumen Sie den Eingang frei, bevor Sie die Wahl treffen, und halten Sie den Ausgang frei."}, grind={[1]={mob="Scheckiger Eber", note="Dichte, meist neutrale normale Mobs. Ziehen Sie jeweils einen Feind nördlich von Das Tal der Prüfungen für Scharfe Zähne auf den Stufen 1-2."}, [2]={mob="Skorpidarbeiter", note="Dichte, meist neutrale normale Mobs. Ziehen Sie jeweils einen Feind nordwestlich des Baus, während Sie Stich des Skorpiden ausführen."}, [3]={mob="Übler Familiar", note="Viele normale Gegner an dem Koven der Burning Blade. Zieh zuerst einzelne Gegner vor der Höhle. Farme bis Stufe 6, bevor du das Tal verlässt."}}, supply={[1]={npc="Rarc"}, [2]={npc="Zlagk"}, [3]={npc="Duokna"}}, steps={[1]={npc="Kaltunk", tgt="Kaltunk"}, [2]={hint="Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen."}, [3]={npc="Gornek", tgt="Gornek"}, [4]={npc="'Tal der Prüfungen'-Geschenkgutschein", npcObj=true, tag="Optional, Muss im Spiel überprüft werden", desc="Akzeptieren Sie nur, wenn Sie ein 'Tal der Prüfungen'-Geschenkgutschein haben. Klicken Sie mit der rechten Maustaste auf den Startgutschein Ihres Rennens. Es gibt keine Abholung auf der Karte."}, [5]={hint="Bringt Magga den 'Tal der Prüfungen'-Geschenkgutschein.", tag="Optional", desc="Akzeptieren Sie nur, wenn Sie ein 'Tal der Prüfungen'-Geschenkgutschein haben."}, [6]={npc="Magga", tgt="Magga", tag="Optional", desc="Akzeptieren Sie nur, wenn Sie ein 'Tal der Prüfungen'-Geschenkgutschein haben."}, [7]={npc="Gornek", tgt="Gornek"}, [8]={npc="Gornek", tgt="Gornek"}, [9]={hint="Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück."}, [10]={hint="Sammelt 6 zurückgelassene Übungswaffen und kehrt dann zu Kzan Thornslash im Höhlenbau zurück."}, [11]={npc="Gornek", tgt="Gornek"}, [12]={npc="Kzan Thornslash", tgt="Kzan Thornslash"}, [13]={npc="Gornek", tgt="Gornek"}, [14]={npc="Galgar", tgt="Galgar"}, [15]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [16]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [17]={text="Räumen Sie das Starttal frei und begeben Sie sich dann zur Höhle im Norden"}, [18]={hint="Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau."}, [19]={hint="Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen."}, [20]={hint="Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", desc="Benutze die Vorarbeiterkeule, um fünf schlafende Peons zu wecken."}, [21]={hint="Tötet 12 üble Familiare.", desc="Hexenmeister: Bringen Sie Ihren Kobold durch die Klassenquest von Ruzan."}, [22]={npc="Hana'zua", tgt="Hana'zua", tag="Optional"}, [23]={hint="Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", tag="Optional"}, [24]={npc="Hana'zua", tgt="Hana'zua", tag="Optional"}, [25]={npc="Hana'zua", tgt="Hana'zua", tag="Optional"}, [26]={hint="Informiert Gornek beim Höhlenbau über Hana'zuas Notlage.", tag="Optional"}, [27]={npc="Gornek", tgt="Gornek", tag="Optional"}, [28]={npc="Gornek", tgt="Gornek"}, [29]={npc="Galgar", tgt="Galgar"}, [30]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [31]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [32]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [33]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [34]={hint="Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", desc="Holen Sie sich die Auswahl in Koven der Burning Blade auf derselben Reise wie das Medaillon."}, [35]={hint="Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade.", desc="Finde Yarrog Schattenbann in der Höhle und plündere den Medaillon der Burning Blade."}, [36]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [37]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [38]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [39]={npc="Verschollenes Tagebuch", npcObj=true, tag="Optional", desc="Suchen Sie Verschollenes Tagebuch neben Zureetha Fargaze."}, [40]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [41]={hint="Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [42]={npc="Frang", tgt="Frang", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [43]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [44]={hint="Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [45]={npc="Frang", tgt="Frang", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [46]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [47]={hint="Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [48]={npc="Rwag", tgt="Rwag", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [49]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [50]={hint="Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [51]={npc="Rwag", tgt="Rwag", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [52]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [53]={hint="Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [54]={npc="Shikrik", tgt="Shikrik", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [55]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [56]={hint="Sprecht mit Shikrik im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [57]={npc="Shikrik", tgt="Shikrik", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [58]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller"}, [59]={hint="Bringt 2 Teufelspirscherhufe zu Canaga Earthcaller im Tal der Prüfungen."}, [60]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller"}, [61]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller", desc="Trinken Sie den Sapta, um den Schwache Erdmanifestation zu sehen."}, [62]={hint="Sucht den Geisterfelsen und trinkt das Erdsapta.", desc="Trinken Sie den Sapta, um den Schwache Erdmanifestation zu sehen."}, [63]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Trinken Sie den Sapta, um den Schwache Erdmanifestation zu sehen."}, [64]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [65]={hint="Bringt den Rohquarz zu Canaga Earthcaller im Tal der Prüfungen.", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [66]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [67]={npc="Gornek", tgt="Gornek"}, [68]={hint="Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen."}, [69]={npc="Jen'shan", tgt="Jen'shan"}, [70]={npc="Gornek", tgt="Gornek"}, [71]={hint="Sprecht mit Jen'shan im Tal der Prüfungen."}, [72]={npc="Jen'shan", tgt="Jen'shan"}, [73]={npc="Gornek", tgt="Gornek"}, [74]={hint="Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}, [75]={npc="Nartok", tgt="Nartok"}, [76]={npc="Gornek", tgt="Gornek"}, [77]={hint="Lest die besudelte Tafel und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}, [78]={npc="Nartok", tgt="Nartok"}, [79]={npc="Ruzan", tgt="Ruzan", desc="Überspringen Sie diese Das Tal der Prüfungen-Route, wenn Sie Ihren Kobold in Deathknell freigeschaltet haben."}, [80]={hint="Bringt 6 Köpfe schändlicher Familiare zu Ruzan.", desc="Überspringen Sie diese Das Tal der Prüfungen-Route, wenn Sie Ihren Kobold in Deathknell freigeschaltet haben."}, [81]={npc="Ruzan", tgt="Ruzan", desc="Überspringen Sie diese Das Tal der Prüfungen-Route, wenn Sie Ihren Kobold in Deathknell freigeschaltet haben."}, [82]={npc="Ruzan", tgt="Ruzan"}, [83]={hint="Sprecht mit Zureetha Fargaze."}, [84]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [85]={npc="Gornek", tgt="Gornek", desc="Geben Sie Scharfe Zähne ab, um das Tablet zu erhalten."}, [86]={hint="Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", desc="Geben Sie Scharfe Zähne ab, um das Tablet zu erhalten."}, [87]={npc="Ken'jai", tgt="Ken'jai", desc="Geben Sie Scharfe Zähne ab, um das Tablet zu erhalten."}, [88]={npc="Ken'jai", tgt="Ken'jai"}, [89]={hint="Sprecht mit Tai'jin in Durotar."}, [90]={npc="Tai'jin", tgt="Tai'jin"}, [91]={npc="Gornek", tgt="Gornek", desc="Geben Sie Scharfe Zähne ab und sehen Sie sich dann den Trainer Magier an."}, [92]={hint="Lest das Glyphenpergament und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", desc="Geben Sie Scharfe Zähne ab und sehen Sie sich dann den Trainer Magier an."}, [93]={npc="Mai'ah", tgt="Mai'ah", desc="Geben Sie Scharfe Zähne ab und sehen Sie sich dann den Trainer Magier an."}, [94]={npc="Gornek", tgt="Gornek", desc="Geben Sie Scharfe Zähne ab und sehen Sie sich dann den Trainer Magier an."}, [95]={hint="Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", desc="Geben Sie Scharfe Zähne ab und sehen Sie sich dann den Trainer Magier an."}, [96]={npc="Mai'ah", tgt="Mai'ah", desc="Geben Sie Scharfe Zähne ab und sehen Sie sich dann den Trainer Magier an."}, [97]={text="Verlassen Sie die Das Tal der Prüfungen und folgen Sie der Straße nach Sen'jin."}}},
    ["01-2"] = {name="Durotar", nameA="Durotar: {a:367} & {a:362}", shortA="Durotar: {a:367} +", tips={{k="取捨", text="Machen Sie Akzeptiert Euer Schicksal. Sammle Segeltuchreste zusammen mit den anderen Burg Tiragarde-Zielen."}, {k="取捨", text="Geben Sie Vernichtet die Verräter ab, um Aus den Wrackteilen geborgen... freizuschalten. Tun Sie es zusammen mit Ein geistvolles Getränk."}, {k="取捨", text="Speichern Sie die Dungeonkette Kluft der Schatten. Wenn Sie planen, Ragefireabgrund auszuführen, nehmen Sie Verborgene Feinde ( → →) von Thrall. Holen Sie sich das Abzeichen für im Burning Blade-Lager im Norden."}, {k="提醒", text="Unter Level 12? Machen Sie Sicherung der Linien, Die Knochenhöhle oder die ersten paar Bedrohung von unten-Quests.", s={{"Unter Level 12?"}, {"Machen Sie Sicherung der Linien, Die Knochenhöhle oder die ersten paar Bedrohung von unten-Quests"}}}}, danger={[1]="Die Treppen und Türen in Burg Tiragarde können Matrosen von oben ziehen. Räumen Sie zuerst die Außenwand und den Eingang frei.", [2]="Meeresriesen durchstreifen das Naga-Gebiet an der Nordküste. Eliminiere nahegelegene Mobs, bevor du einen ziehst. Ziehen Sie sich am Ufer zurück, wenn Sie in Schwierigkeiten geraten."}, grind={[1]={mob="Marinesoldat von Kul Tiras", note="Dichte normale Mobs bei Burg Tiragarde. Fahren Sie nach draußen, um Zutritte in den Fluren zu vermeiden. Sammeln Sie Segeltuchreste für die neue Tasche."}, [2]={mob="Schlachtwache der Grimmhauer", note="Normale Mobs sammeln sich westlich von Klingenhügel. Fahren Sie am Lagerrand entlang und achten Sie auf Patrouillen. Mit Übergriff koppeln."}, [3]={mob="Sturmhexe der Staubschwingen", note="Normale Mobs tummeln sich im nördlichen Durotar. Verwenden Sie die Abdeckung, um die Rollen heranzuziehen. Machen Sie Sicherung der Linien oder mahlen Sie vor Orgrimmar auf 12."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Gastwirt Grosk"}, [3]={npc="Wuark"}, [4]={npc="Gastwirt Grosk"}, [5]={npc="Ghrawt"}, [6]={npc="Doras"}}, steps={[1]={npc="Ukor", tgt="Ukor", desc="Suchen Sie nach Ukor auf dem Weg von Das Tal der Prüfungen zu Sen'jin."}, [2]={hint="Sprecht mit Meister Gadrin in Sen'jin."}, [3]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [4]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [5]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [6]={npc="Meister Vornal", tgt="Meister Vornal"}, [7]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [8]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [9]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [10]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [11]={npc="Xar'Ti", tgt="Xar'Ti"}, [12]={npc="Meister Vornal", tgt="Meister Vornal"}, [13]={npc="Pa'zula", tgt="Pa'zula", tag="Optional", desc="Tun Sie dies nur, wenn Sie die entzaubernden Materialien bekommen können."}, [14]={text="Checken Sie zuerst bei Klingenhügel ein"}, [15]={hint="Tötet 6 Kammschattenkrabbler und 6 Kammschattenlauerer im Süden von Durotar und berichtet anschließend Gar'tok in Klingenhügel davon."}, [16]={hint="Bringt das Tagebuch zu Brakk in Klingenhügel.", tag="Optional"}, [17]={npc="Brakk", tgt="Brakk", tag="Optional"}, [18]={npc="Brakk", tgt="Brakk", tag="Optional"}, [19]={hint="Setzt Euch an Brakks einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", tag="Optional"}, [20]={npc="Brakk", tgt="Brakk", tag="Optional"}, [21]={npc="Brakk", tgt="Brakk", tag="Optional"}, [22]={npc="Brakk", tgt="Brakk", tag="Optional", desc="Lernen Sie zuerst Kürschnerei. Geben Sie an der Haltestelle Orgrimmar ein."}, [23]={hint="Sprecht mit Orgnil Soulscar in Klingenhügel."}, [24]={hint="Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel."}, [25]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [26]={npc="Gar'Thok", tgt="Gar'Thok"}, [27]={npc="Gastwirt Grosk", tgt="Gastwirt Grosk"}, [28]={text="Binden Sie bei Klingenhügel Ihren Ruhestein mit Gastwirt Grosk (51.51, 41.64)."}, [29]={npc="Gar'Thok", tgt="Gar'Thok"}, [30]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [31]={npc="Koch Torka", tgt="Koch Torka"}, [32]={npc="Gar'Thok", tgt="Gar'Thok"}, [33]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Handgefertigte Ledertasche"}}, [34]={npc="Turroc", tgt="Turroc"}, [35]={npc="Koch Torka", tgt="Koch Torka"}, [36]={hint="Sprecht mit Koch Torka in Klingenhügel, um das Kochen zu erlernen.", tag="Optional"}, [37]={npc="Koch Torka", tgt="Koch Torka", tag="Optional"}, [38]={text="Burg Tiragarde → die Wracks → Kolkarklippe und Die Echoinseln"}, [39]={hint="Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück."}, [40]={hint="Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben."}, [41]={hint="Sammelt die Räuberstreitaxt, den Räuberbogen und den Räuberschild um Burg Tiragarde und bringt sie anschließend zu Turroc in Klingenhügel zurück."}, [42]={npc="Vergilbter Umschlag", npcObj=true, desc="Plündere den Schlüssel von Lieutenant Benedict. Öffnen Sie die Truhe im Obergeschoss für den Vergilbter Umschlag."}, [43]={npc="Ukors verlorener Beutel", npcObj=true, tag="Optional", desc="Wenn Sie das Rudel unterwegs plündern, starten Sie die Quest und begeben Sie sich nach Süden zu Ukor."}, [44]={text="Kehren Sie von Burg Tiragarde zu Klingenhügel zurück. Herd, falls fertig."}, [45]={hint="Bringt Gar'Thok in Klingenhügel Admiral Proudmoores Befehle."}, [46]={npc="Gar'Thok", tgt="Gar'Thok"}, [47]={npc="Gar'Thok", tgt="Gar'Thok"}, [48]={npc="Turroc", tgt="Turroc", desc="A Grunzer von Klingenhügel bietet diese Quest auch an (53.06, 42.48)."}, [49]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Handgefertigte Ledertasche"}}, [50]={npc="Gar'Thok", tgt="Gar'Thok"}, [51]={npc="Gar'Thok", tgt="Gar'Thok", tag="Optional"}, [52]={hint="Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret."}, [53]={hint="Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt."}, [54]={hint="Bringt den Beutel zu Ukor im Süden von Durotar.", tag="Optional"}, [55]={npc="Ukor", tgt="Ukor", tag="Optional"}, [56]={npc="Meister Vornal", tgt="Meister Vornal"}, [57]={hint="Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden."}, [58]={npc="Pal'juh", tgt="Pal'juh", tag="Optional", desc="Finden Sie Pal'juh unter Kolkarklippe. Räumen Sie die Straße frei, bevor Sie mit der Begleitung beginnen."}, [59]={hint="Helft Pal'juh, aus der Kolkarklippe zu entkommen, und berichtet anschließend Meister Vornal in Sen'jin davon.", tag="Optional", desc="Finden Sie Pal'juh unter Kolkarklippe. Räumen Sie die Straße frei, bevor Sie mit der Begleitung beginnen."}, [60]={npc="Meister Vornal", tgt="Meister Vornal", tag="Optional", desc="Finden Sie Pal'juh unter Kolkarklippe. Räumen Sie die Straße frei, bevor Sie mit der Begleitung beginnen."}, [61]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [62]={hint="Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier."}, [63]={hint="Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle."}, [64]={hint="Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln."}, [65]={hint="Besiegt Zalazane."}, [66]={hint="Sammelt 8 vergessene Loagötzen auf den Echoinseln. Bringt sie Meister Gadrin in Sen'jin."}, [67]={hint="Bringt die Eier der Blutkrallenmatriarchin zu Xar'Ti in Sen'jin."}, [68]={hint="Pa'zula in Sen'jin möchte, dass Ihr 3 leuchtende Rückstände sammelt. Leuchtende Rückstände können durch das Entzaubern von verhexten Anhängern gefunden werden, die Trolle auf den Echoinseln fallen lassen.", tag="Optional", desc="Der Anhänger Verhexung ist hier erhältlich. Erhalten Sie Leuchtende Rückstände durch Entzaubern."}, [69]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [70]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [71]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [72]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [73]={npc="Xar'Ti", tgt="Xar'Ti"}, [74]={npc="Pa'zula", tgt="Pa'zula", tag="Optional"}, [75]={text="Benutzen Sie Ihr Ruhestein, um nach Klingenhügel zurückzukehren, oder nehmen Sie die Nordstraße."}, [76]={npc="Koch Torka", tgt="Koch Torka"}, [77]={npc="Gar'Thok", tgt="Gar'Thok"}, [78]={text="Westlich von Klingenhügel und nördlich von Durotar"}, [79]={hint="Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer."}, [80]={hint="Koch Torka in Klingenhügel möchte, dass Ihr 8 Kaktusfeigen im Revier der Grimmhauer westlich der Stadt sammelt."}, [81]={npc="Gar'Thok", tgt="Gar'Thok"}, [82]={npc="Koch Torka", tgt="Koch Torka"}, [83]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", desc="Min. Stufe 9."}, [84]={hint="Findet Heglan Shadeeye nördlich von Burg Tiragarde.", desc="Min. Stufe 9."}, [85]={npc="Heglan Shadeeye", tgt="Heglan Shadeeye", desc="Min. Stufe 9."}, [86]={npc="Heglan Shadeeye", tgt="Heglan Shadeeye"}, [87]={hint="Findet Hinweise darauf, was Heglan Shadeeye angegriffen hat."}, [88]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [89]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [90]={hint="Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel."}, [91]={hint="Sammelt 9 Nagastachelflossen ein."}, [92]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [93]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [94]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [95]={hint="Tötet den Meeresriesen an der Nordküste von Durotar und bringt einen Beweis für Euren Erfolg zurück.", tag="Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [96]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [97]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [98]={hint="Sprecht mit Margoz."}, [99]={npc="Margoz", tgt="Margoz"}, [100]={npc="Margoz", tgt="Margoz"}, [101]={hint="Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder."}, [102]={npc="Margoz", tgt="Margoz"}, [103]={npc="Margoz", tgt="Margoz", tag="Optional"}, [104]={text="Optional EP vor Level 12"}, [105]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [106]={hint="Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar.", tag="Optional"}, [107]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [108]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [109]={hint="Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen.", tag="Optional"}, [110]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [111]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Optional"}, [112]={hint="Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal.", tag="Optional"}, [113]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Optional"}, [114]={npc="Matte Sturmkugel", npcObj=true, tag="Optional", desc="Akzeptiere nur, wenn du das Matte Sturmkugel plünderst."}, [115]={hint="Bringt die matte Sturmkugel zu Rezlak in der Nähe der Staubwindklamm.", tag="Optional", desc="Akzeptiere nur, wenn du das Matte Sturmkugel plünderst."}, [116]={npc="Rezlak", tgt="Rezlak", tag="Optional", desc="Akzeptiere nur, wenn du das Matte Sturmkugel plünderst."}, [117]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [118]={hint="Bringt 5 geladene Donnerechsenorgane zu Rezlak in der Nähe der Staubwindklamm.", tag="Optional"}, [119]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [120]={npc="Halikors Huf", npcObj=true, tag="Optional", desc="Wenn Sie Halikor finden und ihn besiegen können, plündern Sie seinen Huf."}, [121]={text="Orgrimmar-Pickups und Crossroads-Übergabe"}, [122]={text="Für Orgrimmar-Quests oder Schulungen folgen Sie der Hauptstraße nach Norden durch das Südtor. Erfahren Sie mehr über Doras' Flugroute (45.12, 63.89) und geben Sie Quests in der Nähe ab."}, [123]={hint="Bringt Nazgrel in Thralls Kammer in Orgrimmar Admiral Proudmoores Befehle.", tag="Optional"}, [124]={npc="Nazgrel", tgt="Nazgrel", tag="Optional"}, [125]={hint="Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster.", tag="Optional"}, [126]={npc="Neeru Fireblade", tgt="Neeru Fireblade", tag="Optional"}, [127]={hint="Geht nach Orgrimmar und sprecht mit Thuwd, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", tag="Optional"}, [128]={npc="Thuwd", tgt="Thuwd", tag="Optional"}, [129]={hint="Bringt Halikors Huf nach Orgrimmar.", tag="Optional"}, [130]={npc="Kamari", tgt="Kamari", tag="Optional"}, [131]={text="Nachdem Sie die Stadtquest abgegeben haben, gehen Sie zu Klingenhügel oder laufen Sie entlang der Hauptstraße nach Süden. Überspringen Sie diese Reise, wenn Sie außerhalb der Stadt geblieben sind."}, [132]={npc="Takrin Pathseeker", tgt="Takrin Pathseeker", desc="Erfordert Level 10. Warten Sie bis etwa 12, um zum Crossroads zu gelangen."}, [133]={hint="Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke."}, [134]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [135]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [136]={text="Gehen Sie von Farwatch-Posten nach Westen. Biegen Sie an der T-Kreuzung Richtung Süden zur Crossroads ab."}, [137]={hint="Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen."}, [138]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [139]={npc="Kaplak", tgt="Kaplak", desc="Orc Einstiegsquest. Trolle können Die Shattered-Hand direkt von Therzok abholen."}, [140]={hint="Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", desc="Orc Einstiegsquest. Trolle können Die Shattered-Hand direkt von Therzok abholen."}, [141]={npc="Therzok", tgt="Therzok", desc="Orc Einstiegsquest. Trolle können Die Shattered-Hand direkt von Therzok abholen."}, [142]={npc="Therzok", tg