    [1947] = {n="Reise in die Marschen", d="Sprecht mit Tabetha."},
    [1948] = {n="Gegenstände der Macht", d="Bringt 1 Stück Jade und den vom Blitz aufgeladenen Dornbusch zu Tabetha in den Marschen von Dustwallow.", objs={"Zinnvorkommen", "Goldvorkommen", "Eisenvorkommen", "Vom Blitz aufgeladener Dornbusch"}},
    [1949] = {n="Verborgene Geheimnisse", d="Sprecht mit Magus Tirth in der schimmernden Ebene."},
    [1950] = {n="Der Knüller schlechthin", d="Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück.", tgo={{"Eisenherz Johnson"}}},
    [1951] = {n="Rituale der Macht", d="Bringt das Buch 'Rituale der Macht' zu Tabetha in den Marschen von Dustwallow.", objs={"Rituale der Macht"}},
    [1952] = {n="Der Zauberstab des Magiers", d="Sprecht nach ihrem Ritual mit Tabetha.", star={"Zauberstab des Eisfurors / Zauberstab der Netherkraft / Zauberstab des Wutfeuers"}},
    [1953] = {n="Rückkehr in die Marschen", d="Sprecht mit Tabetha."},
    [1954] = {n="Die Höllenkugel", d="Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow.", tgo={{"Beschwörer der Burning Blade"}}},
    [1955] = {n="Die Austreibung", d="Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", tgo={{"Dämon der Kugel"}}},
    [1956] = {n="Macht in Uldaman", d="Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha.", tgo={{"Obsidianschildwache"}}},
    [1957] = {n="Manawogen", d="Vernichtet 12 Manawogen innerhalb des Zeitlimits.", tgo={{"Manawoge"}}},
    [1958] = {n="Himmlische Macht"},
    [1959] = {n="Meldung bei Anastasia", d="Sprecht mit Anastasia Hartwell."},
    [1960] = {n="Untersuchungen im Alchimistenladen", d="Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hartwell. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Undercity.", objs={"Gefüllte Verwahrungskästen", "Truhe mit Verwahrungskästen", "Inkantation der Manifestation"}},
    [1961] = {n="Materialsammlung", d="Bringt 10 Leinentücher und 6 Manaedelsteine aus Dalaran zu Josef Gregorian.", tgo={{}, {"Lehrling von Dalaran", "Behüter von Dalaran", "Hexer von Dalaran"}}, objs={"Versteckte Geldkassette", "Ramponierte Truhe", "Ramponierte Truhe"}},
    [1962] = {n="Roben des Zauberfeuers", star={"Roben des geringen Zauberfeuers", {"MAGE"}}},
    [1963] = {n="Die Shattered-Hand", d="Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar.", tgo={{"Tazan"}}},
    [1978] = {n="Die Todespirscher", d="Bringt Androns Geschäftsbuch zu Varimathras in der Halle der dunklen Fürstin in Undercity.", star={"Klinge der Geschicklichkeit", {"ROGUE"}}},
    [1998] = {n="Fenwick Thatros", d="Tötet Fenwick Thatros und bringt seinen Kopf zu Mennet Carkad im Schurkenviertel von Undercity.", tgo={{"Fenwick Thatros"}}},
    [1999] = {n="Werkzeuge des Handwerks", d="Sucht den Statusbericht von Dalaran und bringt ihn zu Mennet Carkad im Schurkenviertel von Undercity.", objs={"Ambermill-Geldkassette"}},
    [2161] = {n="Die Bürde eines Peons", d="Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel."},
    [2202] = {n="Reagenzsuche in Uldaman", d="Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld.", objs={"Magenta Kappengruppen"}},
    [2258] = {n="Reagenzien-Suche im Ödland", d="Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter.", tgo={{"Verhungernder Bussard", "Bussard", "Riesenbussard"}, {"Klippenkojote", "Wilder Klippenkojote", "Alter Klippenkojote"}, {"Felselementar", "Kleiner Felselementar", "Großer Felselementar"}}},
    [2278] = {n="Die Platinscheiben", d="Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.", tgo={{"Bewahrer der Lehren von Norgannon"}}},
    [2280] = {n="Die Platinscheiben", d="Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff."},
    [2283] = {n="Wiederbeschaffung der Halskette", d="Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt.", tgo={{"Feldmesser der Schattenschmiede", "Grobian der Schattenschmiede", "Buddler der Schattenschmiede"}}},
    [2284] = {n="Wiederbeschaffung der Halskette, Teil 2", d="Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine."},
    [2318] = {n="Übersetzung des Tagebuchs", d="Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland."},
    [2338] = {n="Übersetzung des Tagebuchs", d="Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen."},
    [2339] = {n="Findet die Edelsteine und die Kraftquelle", d="Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.", tgo={{}, {"Grimlok"}, {}, {"Archaedas"}}, objs={"Schattenschmiedecache", "Verdächtige Urne"}},
    [2340] = {n="Ablieferung der Edelsteine", d="Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab."},
    [2341] = {n="Wiederbeschaffung der Halskette, Teil 3", d="Besucht Jarkal Mossmeld in Kargath, um festzustellen, ob er Erfolg gehabt hat."},
    [2342] = {n="Wiederbeschaffte Schätze", d="Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity.", objs={"Familientruhe der Garretts"}},
    [2378] = {n="Suche nach der Shattered-Hand", d="Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul."},
    [2379] = {n="Zando'zan", d="Sprecht an der Kluft der Schatten mit Zando'zan."},
    [2381] = {n="Das Ausplündern der Plünderer", d="Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratchet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrennixs Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden.\nWenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!", tgo={{"Polly"}}},
    [2382] = {n="Wrenix aus Ratchet", d="Reist nach Ratchet und sprecht mit Wrenix dem Jämmerlichen."},
    [2383] = {n="Einfaches Pergament", d="Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen."},
    [2418] = {n="Kraftsteine", d="Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum.", tgo={{"Feldmesser der Schattenschmiede", "Grobian der Schattenschmiede", "Buddler der Schattenschmiede"}, {"Feldmesser der Schattenschmiede", "Grobian der Schattenschmiede", "Buddler der Schattenschmiede"}}},
    [2458] = {n="Undercover", d="Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule.\nSobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand.\nEs ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert."},
    [2460] = {n="Der Shattered-Gruß", d="Führt Shenthul gegenüber den Shattered-Gruß aus.", tgo={{"Shenthul"}}},
    [2478] = {n="Mission: möglich, aber nicht sehr wahrscheinlich", d="Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.\nEliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben.", tgo={{"Mutierte Drohne der Venture Co."}, {"Ausguck der Venture Co."}, {"Patrouille der Venture Co."}, {"Oberster Großknecht Puzik Gallywix"}, {"Großknecht Silixiz"}, {}}, objs={"Gallywix' Schließkassette"}},
    [2479] = {n="Hinotts Hilfe", d="Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.\nUm nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!"},
    [2480] = {n="Hinotts Hilfe", d="Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen."},
    [2521] = {n="Ein Dienst für Kum'isha", d="Falls Ihr auf Euren Reisen durch die verwüsteten Lande je auf eine fehlerlose Draenethystsphäre stoßen solltet, bringt sie zu Kum'isha dem Sammler.\nDoch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben.\nIhr erhaltet eine Belohnung für jede fehlerlose Draenethystsphäre, die Ihr beschaffen könnt.", tgo={{"Schreckensfelsoger", "Ogermagier der Schreckensfelsoger", "Schläger der Schreckensfelsoger"}}},
    [2581] = {n="Kicherfangunterkiefer", d="Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.", tgo={{"Verhungernder Kicherfang", "Kicherfanghyäne", "Verheerer"}, {"Aschmähneneber", "Hölleneber", "Suhlaman"}, {"Skorpokstecher", "Clack der Häscher"}}},
    [2583] = {n="Lebenskraft des Ebers", d="Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.", tgo={{"Aschmähneneber", "Hölleneber", "Suhlaman"}, {"Skorpokstecher", "Clack der Häscher"}, {"Rotsteinbasilisk", "Rotsteinkristallhaut", "Todesauge"}}},
    [2585] = {n="Der Entscheidungsschlag", d="Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.", tgo={{"Skorpokstecher", "Clack der Häscher"}, {"Schwarzer Töter", "Knochenpflücker"}, {"Aschmähneneber", "Hölleneber", "Suhlaman"}}},
    [2601] = {n="Der Biss des Basilisken", d="Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.", tgo={{"Rotsteinbasilisk", "Rotsteinkristallhaut", "Todesauge"}, {"Schwarzer Töter", "Knochenpflücker"}}},
    [2603] = {n="Lebensenergie des Geiers", d="Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.", tgo={{"Schwarzer Töter", "Knochenpflücker"}, {"Verhungernder Kicherfang", "Kicherfanghyäne", "Verheerer"}}},
    [2605] = {n="Der durstige Goblin", d="Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger.", tgo={{"Disteltausammler"}}},
    [2606] = {n="Dem guten Geschmacke", d="Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkle sprecht."},
    [2641] = {n="Sprinkles Geheimzutat", d="Sprinkle in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt.", objs={"Violetter Tragan"}},
    [2661] = {n="Lieferung für Marin", d="Sprinkle möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt."},
    [2662] = {n="Noggenfogger-Elixier", d="Marin Noggenfogger möchte, dass Ihr ihn nochmals ansprecht, wenn er sein Elixier fertig gestellt hat."},
    [2741] = {n="Der Super-Ei-O-Mat", d="Benutzen/Sammeln: Hippogryphen-Ei", objs={"Hippogryphen-Ei"}},
    [2766] = {n="Findet OOX-22/FE!", d="Bringt das Notrufsignal zu Oglethorpes Leitroboter in einer Höhle in der Nähe des Wildschrammtals."},
    [2767] = {n="Die Rettung von OOX-22/FE", d="Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."},
    [2768] = {n="Wünschel-mato-Rute", d="Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle.", tgo={{"Sergeant Bly"}}, star={"Masons Bruderschaftsring", {"ROGUE", "HUNTER", "DRUID"}}},
    [2770] = {n="Gahz'rilla", d="Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe.", tgo={{"Gahz'rilla"}}},
    [2781] = {n="GESUCHT: Kalif Skorpidstich", d="Bringt Chefingenieur Bilgewhizzle in Gadgetzan den Kopf von Kalif Skorpidstich.", tgo={{"Kalif Skorpidstich"}}},
    [2822] = {n="Das Zeichen der Qualität", d="Bringt Jangdor Swiftstrider im Camp Mojache 10 dicke Yetibälge.", tgo={{"Wildschrammyeti", "Titanischer Wildschrammyeti", "Wütender Wildschrammyeti"}}},
    [2841] = {n="Maschinenkriege", d="Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar.", tgo={{}, {"Robogenieur Thermaplugg"}}, objs={"Thermapluggs Safe"}},
    [2842] = {n="Chefingenieur Scooty", d="Sprecht mit Scooty in Booty Bay."},
    [2843] = {n="Gnomer-weeeeg!", d="Wartet, bis Scooty den Goblin-Transponder kalibriert hat.", tgo={{"Scooty"}}},
    [2846] = {n="Tiara der Tiefen", d="Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow.", tgo={{"Wasserbeschwörerin Velratha"}}},
    [2862] = {n="Krieg gegen die Waldpfoten", d="Bringt Hadoken Swiftstrider im Camp Mojache 10 Mähnen eines Waldpfotengnolls.", tgo={{"Bastard der Waldpfoten", "Fallensteller der Waldpfoten", "Schläger der Waldpfoten"}}},
    [2863] = {n="Schlag gegen die Alphas", d="Tötet 5 Alphas der Waldpfoten und kehrt innerhalb einer Stunde zu Hadoken Swiftstrider zurück.", tgo={{"Alpha der Waldpfoten"}}},
    [2865] = {n="Skarabäuspanzerschalen", d="Bringt Tran'rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen.", tgo={{"Skarabäus"}}},
    [2873] = {n="Stoleys Lieferung", d="Bringt Stoleys Lieferung zu Stoley nach Steamwheedle.", objs={"Gestohlene Fracht"}},
    [2874] = {n="Lieferung für MacKinley", d="Bringt Stoleys Flasche zu \"Seewolf\" MacKinley in Booty Bay."},
    [2875] = {n="GESUCHT: Andre Feuerbart", d="Bringt Sicherheitschef Bilgewhizzle in Steamwheedle Andres Kopf.", tgo={{"Andre Feuerbart"}}},
    [2876] = {n="Schiffzeitpläne", d="Berichtet den Behörden in Steamwheedle von den Schiffzeitplänen."},
    [2902] = {n="Waldpfotennachforschung", d="Findet die Gnoll-Schlachtpläne irgendwo in den Gnoll-Lagern südlich vom Camp Mojache."},
    [2903] = {n="Die Schlachtpläne", d="Bringt die Schlachtpläne der Waldpfoten zu Hadoken Swiftstrider ins Camp Mojache."},
    [2904] = {n="Eine schöne Bescherung", d="Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay."},
    [2945] = {n="Schmutzverkrusteter Ring", d="Findet einen Weg, den schmutzverkrusteten Ring zu säubern."},
    [2949] = {n="Die Rückkehr des Rings", d="Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."},
    [2973] = {n="Schimmer für einen neuen Umhang", d="Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Skullsplitter nach Camp Mojache.", tgo={{"Grimmlingflitzer", "Gefangener Grimmlingflitzer"}}},
    [2974] = {n="Eine grausige Entdeckung", d="Bringt 20 Grimmtotemhörner zu Krueg Skullsplitter nach Camp Mojache.", tgo={{"Räuber der Grimmtotem", "Naturalist der Grimmtotem", "Schamane der Grimmtotem"}}},
    [2975] = {n="Die Oger von Feralas", d="Rok Orhan im Camp Mojache will, dass Ihr 10 Oger der Gordunni, 10 Magier der Gordunni und 5 Schläger der Gordunni tötet.", tgo={{"Oger der Gordunni"}, {"Ogermagier der Gordunni"}, {"Schläger der Gordunni"}}},
    [2976] = {n="Eine grausige Entdeckung", d="Bringt die Kiste mit Grimmtotemhörnern zu Belgrom Rockmaul nach Orgrimmar."},
    [2978] = {n="Die Gordunnischriftrolle", d="Bringt die Gordunnischriftrolle zu Rok Orhan ins Camp Mojache."},
    [2979] = {n="Dunkle Zeremonie", d="Rok Orhan im Camp Mojache will, dass Ihr eine Gordunnikugel findet.", tgo={{"Magierlord der Gordunni"}}},
    [2980] = {n="Die Oger von Feralas", d="Rok Orhan im Camp Mojache will, dass Ihr 10 Schamanen der Gordunni, 10 Hexenmeister der Gordunni und 5 Raufer der Gordunni tötet.", tgo={{"Schamane der Gordunni"}, {"Hexenmeister der Gordunni"}, {"Raufer der Gordunni"}}},
    [2983] = {n="Ruf des Feuers", d="Sucht Kranal Fiss im Brachland."},
    [2984] = {n="Ruf des Feuers", d="Sucht Kranal Fiss im Brachland."},
    [2987] = {n="Gordunnikobalt", d="Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt.", objs={"Gordunnierdhügel"}},
    [2996] = {n="Die Suche nach Strahad", d="Sprecht mit Strahad Farsan in Ratchet."},
    [3001] = {n="Die Suche nach Strahad", d="Findet Strahad Farsan in Ratchet."},
    [3002] = {n="Die Gordunnikugel", d="Bringt die Gordunnikugel zu Uthel'nay in die Dunkeldornen-Lodge in Orgrimmar."},
    [3042] = {n="Trollaushärter", d="Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan.", tgo={{"Schattenzauberer der Sandfury", "Bluttrinker der Sandfury", "Hexendoktor der Sandfury"}}},
    [3062] = {n="Dunkles Herz", d="Talo Thornhoof im Camp Mojache will das dunkle Herz von Edana Hasskralle.", tgo={{"Edana Hasskralle"}}},
    [3063] = {n="Rache an den Nordschwingen", d="Talo Thornhoof möchte, dass Ihr 4 Harpyien der Nordschwingen, 4 Wildfedern der Nordschwingen, 4 Windruferinnen der Nordschwingen und 4 Töter der Nordschwingen erschlagt.", tgo={{"Harpyie der Nordschwingen"}, {"Wildfeder der Nordschwingen"}, {"Töterin der Nordschwingen"}, {"Windruferin der Nordschwingen"}}},
    [3065] = {n="Einfache Schrifttafel", d="Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen."},
    [3082] = {n="Geätzte Schrifttafel", d="Sprecht mit Jen'shan im Tal der Prüfungen."},
    [3083] = {n="Verschlüsselte Schrifttafel", d="Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen."},
    [3084] = {n="Mit Runen beschriftete Schrifttafel", d="Sprecht mit Shikrik im Tal der Prüfungen."},
    [3085] = {n="Geheiligte Schrifttafel", d="Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen."},
    [3086] = {n="Glyphen-Schrifttafel", d="Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen."},
    [3087] = {n="Geätztes Pergament", d="Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen."},
    [3088] = {n="Verschlüsseltes Pergament", d="Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen."},
    [3089] = {n="Mit Runen beschriftetes Pergament", d="Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen."},
    [3090] = {n="Besudeltes Pergament", d="Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."},
    [3091] = {n="Einfache Notiz", d="Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache."},
    [3092] = {n="Geätzte Notiz", d="Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa."},
    [3093] = {n="Mit Runen beschriftete Notiz", d="Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache."},
    [3094] = {n="Tiefgrüne Notiz", d="Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache."},
    [3095] = {n="Einfache Rolle", d="Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Deathknell."},
    [3096] = {n="Verschlüsselte Rolle", d="Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Deathknell."},
    [3097] = {n="Geheiligte Rolle", d="Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Deathknell."},
    [3098] = {n="Glyphen-Rolle", d="Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Deathknell."},
    [3099] = {n="Besudelte Rolle", d="Lest die besudelte Schriftrolle und sprecht mit Maximillion in Deathknell."},
    [3121] = {n="Eine seltsame Anforderung", d="Bringt den Schrumpfkopf zu Neeru Fireblade in Orgrimmar."},
    [3122] = {n="Kehrt zu Hexendoktor Uzer'i zurück", d="Bringt Neerus Kräuterbeutel zu Hexendoktor Uzer'i in Feralas."},
    [3123] = {n="Das Gefäß wird getestet", d="Reist ins Hinterland und spürt die Wildekin auf. Schaltet 10 davon aus und benutzt dann das Muisekgefäß, um die gefallenen Wildekin zu schrumpfen und einzufangen.\nBringt anschließend 10 Einheiten Muisek von Wildekins und das Muisekgefäß zu Hexendoktor Uzer'i in Feralas.", tgo={{"Heimtückische Eulenbestie", "Primitive Eulenbestie", "Wilde Eulenbestie"}}},
    [3124] = {n="Muisek von Hippogryphen", d="Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", tgo={{"Fransenfederhippogryph", "Fransenfederflügler", "Fransenfederhimmelsstürmer"}}},
    [3125] = {n="Muisek von Feendrachen", d="Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", tgo={{"Grimmlingdrache", "Grimmlingflitzer"}}},
    [3126] = {n="Muisek von Treants", d="Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", tgo={{"Wandernder Waldgänger"}}},
    [3127] = {n="Muisek von Bergriesen", d="Schaltet 7 Landgänger oder Klippenriesen aus. Benutzt das Muisekgefäß, um die gefallenen Bergriesen zu schrumpfen und einzufangen.", tgo={{"Landgänger", "Klippenriese", "Geschrumpfter Landgänger"}}},
    [3128] = {n="Natürliche Materialien", d="Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache.", tgo={{"Wandernder Waldgänger"}, {"Grimmlingdrache", "Grimmlingflitzer", "Landgänger"}, {"Heimtückische Eulenbestie", "Primitive Eulenbestie", "Wilde Eulenbestie"}, {"Heimtückische Eulenbestie", "Primitive Eulenbestie", "Wilde Eulenbestie"}}},
    [3129] = {n="Waffen des Geistes", d="Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet."},
    [3161] = {n="Gahz'ridian", d="Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt.", objs={"Gahz'ridian"}},
    [3221] = {n="Sprecht mit Renferrel", d="Sprecht mit Apotheker Renferrel in dem Grabmal."},
    [3261] = {n="Jorn Skyseer", d="Sprecht im Camp Taurajo mit Jorn Skyseer."},
    [3281] = {n="Gestohlenes Silber", d="Bringt das gestohlene Silber zu Gazrog in Crossroads.", objs={"Gestohlenes Silber"}},
    [3301] = {n="Mura Runetotem", d="Sprecht mit Mura Runetotem in dem Grabmal."},
    [3341] = {n="Das Ende bringen", d="Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt.", tgo={{"Amnennar der Kältebringer"}}},
    [3362] = {n="Disteltal", d="Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.", tgo={{"Knorriger Distelwandler"}, {"Distelwurzelformer"}}},
    [3369] = {n="Alptraum", d="Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten."},
    [3373] = {n="Die Essenz des Eranikus", d="Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet."},
    [3376] = {n="Tötet Spitzhauer!", d="Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa.", tgo={{"Häuptling Spitzhauer Dornenmantel"}}},
    [3380] = {n="Der versunkene Tempel", d="Sucht Marvon Rivetseeker in Tanaris."},
    [3441] = {n="Göttliche Vergeltung", d="Lasst Velarok Windblade seine Geschichte erzählen.", tgo={{"Kalaran Windblade"}}},
    [3442] = {n="Die fehlerlose Flamme", d="Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade.", tgo={{"Lodernder Elementar", "Infernoelementar", "Magmaelementar"}, {"Ausgehärteter Kriegsgolem", "Schwerer Kriegsgolem", "Magmaelementar"}}},
    [3443] = {n="Das Schmieden des Schafts", d="Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade.", tgo={{"Geologe der Dunkeleisenzwerge", "Dampfschmied der Dunkeleisenzwerge", "Sklavenarbeiter"}}},
    [3444] = {n="Der runde Stein", d="Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.", objs={"Marvons Truhe"}},
    [3446] = {n="In die Tiefen", d="Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends."},
    [3447] = {n="Das Geheimnis des Kreises", d="Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt."},
    [3452] = {n="Die Ummantelung der Flamme", d="Bringt ein Symbol von Ragnaros zu Velarok Windblade.", tgo={{"Twilight-Dunkelschamane", "Twilight-Feuerwache", "Twilight-Geomant"}}},
    [3453] = {n="Die Fackel der Vergeltung", d="Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat.", tgo={{"Kalaran Windblade"}}},
    [3454] = {n="Die Fackel der Vergeltung", d="Nehmt die Fackel der Vergeltung."},
    [3462] = {n="Knappe Maltrake", d="Sprecht mit dem Knappen Maltrake."},
    [3463] = {n="Setzt sie in Brand!", d="Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", objs={"Wachposten-Kohlenpfanne"}},
    [3481] = {n="Plunder...", d="Öffnet die Truhe."},
    [3501] = {n="Im Dutzend besser", d="Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt.", tgo={{"Schreckensfelsoger", "Ogermagier der Schreckensfelsoger", "Schläger der Schreckensfelsoger"}}},
    [3504] = {n="Verraten", d="Bringt den versiegelten Brief zu Ag'tor Bloodfist nach Azshara."},
    [3505] = {n="Verraten", d="Tötet 6 Blutelfenwiederbeschaffer und 6 Blutelfenfeldmesser, bevor Ihr Euch aufmacht, Rimtoris Quelle der Macht zu finden.", tgo={{"Blutelfenwiederbeschafferin"}, {"Blutelfenfeldmesser"}}},
    [3517] = {n="Wissen stehlen", d="Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai für Jediga in Valormok.", objs={"Schrifttafel von Beth'Amara", "Schrifttafel von Jin'yael", "Schrifttafel von Markri", "Schrifttafel von Sael'hai"}},
    [3518] = {n="Lieferung an Magatha Grimmtotem", d="Bringt die Schrifttafel von Beth'Amara zu Magatha Grimmtotem in Thunder Bluff."},
    [3520] = {n="Kreischergeister", d="Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", tgo={{"Kreischergeist"}}},
    [3523] = {n="Geißel der Niederungen", d="Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab."},
    [3525] = {n="Ausschalten des Götzen", d="Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."},
    [3527] = {n="Die Prophezeiung von Mosh'aru", d="Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.", tgo={{"Theka der Märtyrer", "Theka der Märtyrer Gestaltwandlung"}, {"Wasserbeschwörerin Velratha"}}},
    [3528] = {n="Der Gott Hakkar", d="Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris."},
    [3541] = {n="Lieferung an Jes'rimon", d="Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar."},
    [3542] = {n="Lieferung an Andron Gant", d="Bringt die Schrifttafel von Markri zu Andron Gant nach Undercity."},
    [3601] = {n="Kim'jael, fürwahr!", d="Durchsucht den Thalassian-Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Wizzlegoober und bringt ihm dann alles nach Azshara zurück.", objs={"Kim'jaels Ausrüstung"}},
    [3631] = {n="Teufelsross beschwören", d="Sprecht mit Strahad Farsan im Brachland."},
    [3783] = {n="Sind wir endlich da, Yeti?", d="Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook.", tgo={{"Wilder Eisdistelyeti", "Eisdistelyeti"}}},
    [3801] = {n="Dunkeleisenerbe", d="Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten."},
    [3802] = {n="Dunkeleisenerbe", d="Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.", tgo={{"Fineous Darkvire"}}},
    [3821] = {n="Schreckensfels", d="Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist."},
    [3822] = {n="Krom'Grul", d="Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels.", tgo={{"Krom'Grul"}}},
    [3844] = {n="Es ist für jeden ein Geheimnis", d="Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte."},
    [3845] = {n="Es ist für jeden ein Geheimnis", d="Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer."},
    [3881] = {n="Rettungsexpedition", d="Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater.", objs={"Kiste mit Lebensmitteln", "Forscherausrüstung"}},
    [3882] = {n="Knochenklappern", d="Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater.", tgo={{"Stegodon", "Plattenpanzerstegodon", "Stachelstegodon"}}},
    [3884] = {n="Willidens Tagebuch", d="Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater."},
    [3901] = {n="Klappernde Skelette", d="Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid.", tgo={{"Klapperndes Skelett"}}},
    [3902] = {n="Beutesuche in Deathknell", d="Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück.", objs={"Ausrüstungskästen"}},
    [3906] = {n="Disharmonie der Flamme", d="Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt.", tgo={{"Übermeister Pyron"}}},
    [3907] = {n="Disharmonie des Feuers", d="Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart.", tgo={{"Lord Incendius"}, {"Lord Incendius"}}},
    [3908] = {n="Es ist für jeden ein Geheimnis", d="Bringt Linkens Schwert zu Donova Snowden in Winterspring."},
    [3909] = {n="Das Videre-Elixier", d="Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.", tgo={{"Gregan Brewspewer"}}},
    [3912] = {n="Treffen am Grab", d="Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden."},
    [3913] = {n="Grabesstille", d="Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat."},
    [3914] = {n="Linkens Schwert", d="Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab."},
    [3941] = {n="Die Hilfe des Gnoms", d="Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf."},
    [3942] = {n="Linkens Andenken", d="Sucht Eridan Bluewind im südlichen Teil des Teufelswalds."},
    [4021] = {n="Gegenangriff!", d="Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads.", objs={"Krom'zars Flagge"}},
    [4061] = {n="Aufstieg der Maschinen", d="Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.\nEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter.", tgo={{"Großer Obsidianelementar", "Kriegshäscher", "Fehlfunktionierender Häscher"}}},
    [4062] = {n="Aufstieg der Maschinen", d="Bringt die Elementarsplitterprobe zu Lotwil Veriatus.\nIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert."},
    [4081] = {n="SOFORT TÖTEN: Dunkeleisenzwerge", d="Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!\nKriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Gardist der Zorneshämmer"}, {"Aufseher der Zorneshämmer"}, {"Fußsoldat der Zorneshämmer"}}},
    [4084] = {n="Silberherz", d="Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.", tgo={{"Wutklauenbär", "Wutklauengrizzly", "Wutklauenraufer"}, {"Wanderer der Eisenstämme", "Donnerstampfer der Eisenstämme"}}},
    [4102] = {n="Den Teufelswald säubern", d="Bringt 15 Einheiten Blutharz zu Maybess Riverbreeze im Teufelswald.", tgo={{"Wucherborkenschinder", "Wucherborkenschredder", "Dessecus"}}},
    [4120] = {n="Die Kraft der Verderbnis", d="Talo Thornhoff im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt.", tgo={{"Wutklauengrizzly"}, {"Teufelspfotenverheerer"}}},
    [4123] = {n="Das Herz des Berges", d="Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe.", objs={"Herz des Berges"}},
    [4134] = {n="Verlorenes Donnerbräurezept", d="Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept.", tgo={{"Hurley Pestatem", "Pestatems Spießgeselle"}}},
    [4136] = {n="Ribbly Screwspigot", d="Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf.", tgo={{"Ribbly Screwspigot"}}},
    [4145] = {n="Larion und Muigin", d="Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht.", tgo={{"Blutblütenpeitscher"}, {"Blutblütenfalle"}, {"Blutblütenschinder"}, {"Blutblütendrescher"}}},
    [4147] = {n="Marvons Werkstatt", d="Reist zu Marvon Rivetseekers Werkstatt in Ratchet."},
    [4284] = {n="Machtkristalle", d="Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht.", objs={"Roter Machtkristall", "Gelber Machtkristall", "Grüner Machtkristall", "Blauer Machtkristall"}},
    [4285] = {n="Der Nordpylon", d="Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater.", objs={"Nördlicher Kristallpylon"}},
    [4287] = {n="Der Ostpylon", d="Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater.", objs={"Östlicher Kristallpylon"}},
    [4288] = {n="Der Westpylon", d="Findet den Standort des westlichen Kristallpylonen.", objs={"Westlicher Kristallpylon"}},
    [4289] = {n="Die Affen von Un'Goro", d="Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze.", tgo={{"Un'Goro-Gorilla", "Un'Goro-Gorilla"}, {"Un'Goro-Stampfer"}, {"Un'Goro-Donnerer"}}},
    [4290] = {n="Lar'korwis Mahl", d="Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück.", objs={"Frisches Dreschadongerippe"}},
    [4291] = {n="Lar'korwis Fährte", d="Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen.", tgo={{"Lar'korwi-Weibchen"}}},
    [4292] = {n="Ein Köder für Lar'korwi", d="Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Schrifttafel der Sieben", d="Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel.", objs={"Schrifttafel der Sieben"}},
    [4300] = {n="Knochenklingenwaffen", d="Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen.", tgo={{"Ravasaurus", "Ravasaurusläufer", "Ravasaurusjäger"}}},
    [4301] = {n="Der mächtige U'cha", d="Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters.", tgo={{"U'cha"}}},
    [4321] = {n="Die Sache verstehen", d="Sprecht demnächst mit J. D. Collie."},
    [4324] = {n="Yuka Screwspigot", d="Sprecht mit Yuka Screwspigot in der brennenden Steppe."},
    [4402] = {n="Galgars Kaktusapfel Surprise", d="Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen.", objs={"Kaktusapfel"}},
    [4449] = {n="Eingesperrt!", d="Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.", tgo={{"Geologe der Dunkeleisenzwerge"}, {}}, objs={"Alteracgranit", "Ramponierte Truhe", "Robuste Truhe"}},
    [4489] = {n="Teufelsross beschwören", d="Sprecht mit Strahad Farsan in Ratchet."},
    [4490] = {n="Teufelsross beschwören", d="Sprecht in Ratchet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört."},
    [4491] = {n="Etwas Hilfe von guten Freunden", d="Führt Ringo zu Spraggle Frock in Marshals Zuflucht.\nFalls Ringo ohnmächtig werden sollte, verwendet Spraggles Feldflasche, um ihn zu beleben."},
    [4492] = {n="Verloren!", d="Sucht Ringo am Feuerfedergrat."},
    [4494] = {n="Der Marsch der Silithiden", d="Sprecht in Gadgetzan mit Alchimist Pestlezugg."},
    [4496] = {n="Dschungelei", d="Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan.", tgo={{"Wespe der Gorishi", "Arbeiter der Gorishi", "Häscher der Gorishi"}, {}}, objs={"Un'Goro-Erdhaufen"}},
    [4502] = {n="Vulkanische Aktivität", d="Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet.", tgo={{"Versengender Elementar", "Lebendiges Feuer", "Sturmflamme"}}},
    [4503] = {n="Shizzles Flieger", d="Sammelt 8 eingesponnene Dimetrodon-Schuppen und 8 eingesponnene Pterrordax-Schuppen für Shizzle in Marshals Zuflucht.", tgo={{"Junger Dimetrodon", "Dimetrodon", "Alter Dimetrodon"}, {"Pterrordaxjunges", "Pterrordax", "Rasender Pterrordax"}}},
    [4504] = {n="Superkleber", d="Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan.", tgo={{"Teerbestie", "Teerlauerer", "Teerfürst"}}},
    [4505] = {n="Brunnen der Verderbnis", d="Beschafft eine Probe verderbten Wassers vom Mondbrunnen der Jadefeuersatyrn und bringt sie zu Winna Hazzard am Blutgiftposten.", objs={"Der verderbte Mondbrunnen"}},
    [4506] = {n="Verderbte Säbler", d="Bringt Winnas Kätzchen zum verderbten Mondbrunnen, lasst es dort frei und bringt es dann wieder zu Winna zurück.\nSobald Ihr wieder bei Winna seid, klickt auf die Katze, um sie Winna zu übergeben."},
    [4521] = {n="Wilde Wächter", d="Trull Failbane im Teufelswald möchte, dass Ihr 15 tobende Eulenbestien und 15 struppige Eulenbestien tötet.", tgo={{"Tobende Eulenbestie"}, {"Struppige Eulenbestie"}}},
    [4542] = {n="Nachricht zum Freiwindposten", d="Bringt Klippenbehüter Longhorn am Freiwindposten die dringende Nachricht."},
    [4641] = {n="Euer Platz in der Welt", d="Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen."},
    [4724] = {n="Die Herrin der Meute", d="Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte.", tgo={{"Halycon"}}},
    [4726] = {n="Brutlingessenz", d="Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", objs={"Brutlingessenz"}},
    [4729] = {n="Kiblers Exotische Tiere", d="Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler."},
    [4737] = {n="Auf der Suche nach Menara Voidrender", d="Sprecht mit Menara Voidrender im Brachland."},
    [4739] = {n="Auf der Suche nach Menara Voidrender", d="Sprecht mit Menara Voidrender im Brachland."},
    [4742] = {n="Siegel des Aufstiegs", d="Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.\nVaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten.", tgo={{"Hochlord Omokk"}, {"Kriegsmeister Voone"}, {"Oberanführer Wyrmthalak"}, {"Grunzer der Schmetterschilde", "Wachposten der Schmetterschilde", "Akolyt der Schmetterschilde"}}},
    [4743] = {n="Siegel des Aufstiegs", d="Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.\nIn genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!", objs={"Geschmiedetes Siegel des Aufstiegs"}},
    [4767] = {n="Windreiter", d="Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen.", objs={"Ei eines Steilhangflügeldrachen"}},
    [4768] = {n="Die Darkstone-Schrifttafel", d="Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel.", objs={"Darkstone-Schrifttafel"}},
    [4769] = {n="Vivian Lagrave und die Darkstone-Schrifttafel", d="Sprecht mit Schattenmagierin Vivian Lagrave."},
    [4770] = {n="Auf der Heimreise", d="Begleitet Pao'ka Swiftmountain aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Firemane."},
    [4781] = {n="Komponenten für die verzauberte Goldblutrobe", d="Bringt Xizk Goodstitch im Schlingendorntal einen Goldbarren.", objs={"Ramponierte Truhe", "Robuste Truhe", "Geldkassette der Allianz"}},
    [4782] = {n="Komponenten für die verzauberte Goldblutrobe", d="Kehrt zu Menara Voidrender im Brachland zurück."},
    [4783] = {n="Komponenten für die verzauberte Goldblutrobe", d="Bringt Menara Voidrender im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein.", tgo={{"Schurke der Zornsäer", "Schwindler der Zornsäer", "Teufelsanbeter der Zornsäer"}, {"Geringe Höllenbestie", "Dämonenportalwächter"}}},
    [4784] = {n="Komponenten für die verzauberte Goldblutrobe", d="Bringt Menara Voidrender im Brachland Goldgarn, 2 glimmende Kohlen und einen Seelensplitter.", tgo={{"Xizk Goodstitch"}, {"Brennender Verbannter"}, {}}},
    [4785] = {n="Feiner Goldfaden"},
    [4786] = {n="Die fertig gestellte Robe", d="Wartet, bis Menara Voidrender Eure Robe fertig gestellt hat, und sprecht dann noch einmal mit ihr.", tgo={{"Menara Voidrender"}}, star={"Verzauberte Goldblutrobe", {"WARLOCK"}}},
    [4787] = {n="Das uralte Ei", d="Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", objs={"Uraltes Ei"}},
    [4808] = {n="Felnok Steelspring", d="Gebt Felnok Steelspring Tinkees Brief."},
    [4809] = {n="Hörner der Eiswindschimären", d="Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre.", tgo={{"Eiswindjunges", "Eiswindschimäre", "Eiswindverheerer"}}},
    [4810] = {n="Rückkehr zu Tinkee", d="Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen."},
    [4821] = {n="Fremdartiges Ei", d="Bringt Hagar Lightninghoof am Freiwindposten das fremdartige Ei.", objs={"Fremdartiges Ei"}},
    [4841] = {n="Befriedung der Zentauren", d="Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Longhorn am Freiwindposten zurück.", tgo={{"Späher der Galak"}, {"Zänker der Galak"}, {"Windhetzerin der Galak"}}},
    [4842] = {n="Sonderbare Quellen", d="Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr."},
    [4862] = {n="Be-Öh-Es-Eh", d="Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.\nLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.", objs={"Spitzenspinnen-Ei"}},
    [4865] = {n="Wilde Schlange", d="Berichtet Motega Firemane von Euren Entdeckungen."},
    [4881] = {n="Auftragsmordplan", d="Warnt Kanati Greycloud am Weißgipfelposten, dass man vorhat, ihn zu töten."},
    [4903] = {n="Befehl des Kriegsherrn", d="Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt.", tgo={{"Oberanführer Wyrmthalak"}, {"Hochlord Omokk"}, {"Kriegsmeister Voone"}, {}}, objs={"Unauffällige Dokumente"}},
    [4904] = {n="Endlich frei", d="Geleitet Lakota Windsong vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Amberhide."},
    [4921] = {n="In der Schlacht vermisst", d="Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück.", tgo={{"Geschlagener Kadaver"}}},
    [4941] = {n="Eitriggs Weisheit", d="Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.\nIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt."},
    [4961] = {n="Die Säuberung der Kugel von Orahil", d="Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", tgo={{"Dämon der Kugel"}}},
    [4962] = {n="Splitter eines Teufelshundes", d="Nehmt den Felhas-Rubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Teufelshundgeist und den Felhas-Rubin.", tgo={{"Manafresser"}}},
    [4963] = {n="Splitter einer Höllenbestie", d="Nehmt den Infus-Smaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Höllenbestiengeist und den Infus-Smaragd.", tgo={{"Geringe Höllenbestie"}}},
    [4964] = {n="Die fertig gestellte Kugel von Dar'Orahil", d="Wartet, bis Menara Voidrender die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", tgo={{"Menara Voidrender"}}},
    [4966] = {n="Kanati Greycloud schützen", d="Beschützt Kanati Greycloud vor den Angriffen der Zentauren.", tgo={{"Auftragsmörder der Galak"}}},
    [4967] = {n="Wissen der Kugel von Orahil", d="Sprecht mit Menara Voidrender im Brachland."},
    [4969] = {n="Wissen der Kugel von Orahil", d="Sprecht mit Menara Voidrender im Brachland."},
    [4971] = {n="Eine Frage der Zeit", d="Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.\nTötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", tgo={{"Temporaler Parasit"}}},
    [4972] = {n="Tempus fugit", d="Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück.", objs={"Kleine Schließkassette"}},
    [4974] = {n="Für die Horde!", d="Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.", tgo={{"Kriegshäuptling Rend Blackhand"}}},
    [4975] = {n="Die fertig gestellte Kugel von Noh'Orahil", d="Wartet, bis Menara Voidrender die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", tgo={{"Menara Voidrender"}}},
    [4976] = {n="Ablieferung der gesäuberten Kugel", d="Bringt die gesäuberte Höllenkugel zu Menara Voidrender ins Brachland."},
    [4981] = {n="Agentin Bijou", d="Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist."},
    [4982] = {n="Bijous Habseligkeiten", d="Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben.", objs={"Bijous Habseligkeiten"}},
    [4983] = {n="Bijous Aufklärungsbericht", d="Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath."},
    [4984] = {n="Die Tierwelt leidet auch", d="Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", tgo={{"Kranker Wolf"}}},
    [4985] = {n="Die Tierwelt leidet auch", d="Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", tgo={{"Kranker Grizzly"}}},
    [5021] = {n="Besser spät als nie", d="Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts."},
    [5023] = {n="Besser spät als nie", d="Wendet Euch an die königlichen Vorarbeiter von Undercity, um etwas über den Aufenthaltsort von Jeremiah Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung."},
    [5041] = {n="Vorräte für Crossroads", d="Findet die Crossroads-Vorratskisten und bringt sie zu Thork im Brachland zurück.", objs={"Vorratskisten von Crossroads"}},
    [5049] = {n="Der Jammer des Jeremiah", d="Sucht Jeremiah Payson in Undercity und findet heraus, ob er tatsächlich Jeremiah Felstone ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Felstone für ihn gepackt hat."},
    [5050] = {n="Glücksbringer", d="Bringt Janice Felstone in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück."},
    [5051] = {n="Zwei Hälften vereint", d="Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.\nGebt den Glücksbringer Janice Felstone auf demTeufelssteinfeld in den Westlichen Pestländern."},
    [5052] = {n="Blutsplitter von Agammagan", d="Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.\nSammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet.", tgo={{"Jäger der Borstennacken", "Wassersucher der Borstennacken", "Dornenwirker der Borstennacken"}}},
    [5054] = {n="Ursius von den Splitterzahnbären", d="Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Ursius tötet.", tgo={{"Ursius"}}},
    [5058] = {n="Mrs. Dalsons Tagebuch"},
    [5059] = {n="Weggeschlossen", d="Beute von: Wanderndes Skelett", tgo={{"Wanderndes Skelett"}}},
    [5060] = {n="Weggeschlossen", d="Beute von: Bauer Dalson", tgo={{"Bauer Dalson"}}},
    [5062] = {n="Hochheiliges Feuer", d="Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff.", objs={"Brandpulveragave"}},
    [5064] = {n="Grimmtotemspionage", d="Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück.", objs={"Dokumententruhe"}},
    [5082] = {n="Bedrohung durch die Winterfelle", d="Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.", tgo={{"Pfadfinder der Winterfelle"}, {"Höhlenbehüter der Winterfelle"}, {"Totemiker der Winterfelle"}}},
    [5083] = {n="Feuerwasser der Winterfelle", d="Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring."},
    [5084] = {n="Der Verderbnis erliegen", d="Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis."},
    [5085] = {n="Geheimnisvoller Glibber", d="Berichtet Donova Snowden von Euren Entdeckungen."},
    [5086] = {n="Toxinschrecken", d="Sammelt 3 Toxinschrecken-Tröpfchen für Donova Snowden in Winterspring.", tgo={{"Toxinschrecken"}}},
    [5087] = {n="Läufer der Winterfelle", d="Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen.", tgo={{"Läufer der Winterfelle"}}},
    [5096] = {n="Scharlachrote Ablenkung", d="Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.\nLasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück."},
    [5098] = {n="Turm um Turm", d="Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, Westliche Pestländer, zurück.", tgo={{"Turm 1 von Andorhal"}, {"Turm 2 von Andorhal"}, {"Turm 3 von Andorhal"}, {"Turm 4 von Andorhal"}}},
    [5121] = {n="Oberhäuptling der Winterfelle", d="Donova Snowden in Winterspring möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt.", tgo={{"Oberhäuptling der Winterfelle"}}},
    [5122] = {n="Das Medaillon des Glaubens", d="Benutzen/Sammeln: Malors Geldkassette", objs={"Malors Geldkassette"}},
    [5123] = {n="Das letzte Stück", d="Bringt das kunstlos geschriebene Logbuch zu Donova Snowden in Winterspring."},
    [5125] = {n="Aurius' Abrechnung"},
    [5147] = {n="GESUCHT: Arnak Grimmtotem", d="Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Longhorn im Freiwindposten.", tgo={{"Arnak Grimmtotem"}}},
    [5149] = {n="Pamelas Puppe", d="Sucht Pamelas Puppe."},
    [5151] = {n="Hyperkondensator-Dingsda", d="Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Bearingshiner zurück.", tgo={{"Wütender Panther"}}},
    [5152] = {n="Tante Marlene", d="Sprecht mit Marlene, südlich der Ruinen von Andorhal."},
    [5153] = {n="Ein seltsamer Historiker", d="Bringt Josephs Ehering zu Chromie.", objs={"Joseph Redpaths Monument"}},
    [5154] = {n="Die Annalen von Darrowshire", d="Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal.", objs={"Modriger Foliant"}},
    [5155] = {n="Streitmacht von Jaedenar", d="Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", tgo={{"Hund von Jaedenar"}, {"Wächter von Jaedenar"}, {"Adept von Jaedenar"}, {"Kultist von Jaedenar"}}},
    [5156] = {n="Die Verderbnis überprüfen", d="Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.", tgo={{"Entropische Bestie"}, {"Entropischer Schrecken"}}},
    [5157] = {n="Verderbtes Wasser sammeln", d="Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", objs={"der verderbte Mondbrunnen von Jaedenar"}},
    [5158] = {n="Spirituelle Hilfe suchen", d="Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer."},
    [5159] = {n="Gesäubertes Wasser wird zum Teufelswald gebracht", d="Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald."},
    [5163] = {n="Sind wir endlich da, Yeti?", d="Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:\nLegacki in Everlook (Winterspring)\nSprinkle in Gadgetzan (Tanaris)\nQuixxil in Marshals Zuflucht (Un'Goro Krater)\nWenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück.", tgo={{"Legacki"}, {"Sprinkle"}, {"Quixxil"}}},
    [5165] = {n="Übergießen der Flammen des Schutzes", d="Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser.", objs={"Kohlenpfanne des Schmerzes", "Kohlenpfanne der Bosheit", "Kohlenpfanne des Leidens", "Kohlenpfanne des Hasses"}},
    [5211] = {n="Verteidiger von Darrowshire", d="Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.", tgo={{"Geist von Darrowshire"}}},
    [5212] = {n="Das Fleisch lügt nicht", d="Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", tgo={{"Verheerter Kadaver", "Geschundener Kadaver", "Seuchenghul"}}},
    [5213] = {n="Der aktive Wirkstoff", d="Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.", objs={"Geißeldaten"}},
    [5214] = {n="Der große Ezra Grimm", d="Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.", tgo={{"Ezra Grimm"}}},
    [5228] = {n="Die Geißelkessel", d="Sprecht mit der Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer."},
    [5229] = {n="Ziel: Teufelssteinfeld", d="Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Gallenschlund"}}},
    [5230] = {n="Rückkehr zum Bollwerk", d="Bringt die gefüllte Flasche: Teufelssteinfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer."},
    [5231] = {n="Ziel: Dalsons Tränenfeld", d="Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Malvinius"}}},
    [5232] = {n="Rückkehr zum Bollwerk", d="Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer."},
    [5233] = {n="Ziel: Das trostlose Feld", d="Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Razarch"}}},
    [5234] = {n="Rückkehr zum Bollwerk", d="Bringt die gefüllte Flasche: Das trostlose Feld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer."},
    [5235] = {n="Ziel: Gahrrons Trauerfeld", d="Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Rachseele"}}},
    [5236] = {n="Rückkehr zum Bollwerk", d="Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer."},
    [5238] = {n="Mission erfüllt!", star={"Tapferes Kurzschwert", {"PALADIN", "MAGE", "WARLOCK"}}},
    [5241] = {n="Onkel Carlin", d="Sucht Carlin Redpath."},
    [5242] = {n="Der endgültige Schlag", d="Tötet Moora und Salia und bringt den Kopf von Schattenlord Fel'dan zu Greta Mosshoof im Teufelswald.", tgo={{"Moora"}, {"Salia"}, {"Schattenlord Fel'dan"}}},
    [5243] = {n="Häuser der Heiligen", d="Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", objs={"Vorratskiste", "Vorratskiste von Stratholme"}},
    [5251] = {n="Der Archivar", d="Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", tgo={{"Archivar Galford"}, {}}, objs={"Scharlachrotes Archiv"}},
    [5281] = {n="Die ruhelosen Seelen", d="Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde."},
    [5282] = {n="Die ruhelosen Seelen", d="Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück.", tgo={{"Ruhelose Seele"}}},
    [5306] = {n="Schlangenstein der Schattenjägerin", d="Begebt Euch zur Blackrockspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", tgo={{"Schattenjägerin Vosh'gajin"}}},
    [5341] = {n="Das Familienvermögen der Barovs", d="Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.", objs={"Die Besitzurkunde für Brill", "Die Besitzurkunde für Caer Darrow", "Die Besitzurkunde für Southshore", "Die Besitzurkunde für Tarrens Mühle"}},
    [5361] = {n="Stammbaum", d="Bringt den Bericht von Klippenbehüter Longhorn zu Nataka Longhorn am Geistwandlerposten in Desolace."},
    [5381] = {n="Hand von Iruxos", d="Holt den Dämonenkasten aus der Festung Thunder Axe und kehrt damit zu Taiga Wisemane nach Shadowprey zurück.", tgo={{"Dämonengeist"}}},
    [5382] = {n="Doktor Theolen Krastinov, der Schlächter", d="Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Doktor Theolen Krastinov"}, {}, {}}, objs={"Überreste von Eva Sarkhoff", "Überreste von Lucien Sarkhoff"}},
    [5386] = {n="Der Fang des Tages", d="Sprecht mit Jinar'Zillen in Shadowprey und bringt Nataka Longhorn dann 2 Blutbauchfische.", tgo={{"Jinar'Zillen"}}},
    [5441] = {n="Faule Peons", d="Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", tgo={{"Fauler Peon"}}},
    [5481] = {n="Gordos Aufgabe", d="Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Brill-Friedhof.", objs={"Düsterkraut"}},
    [5482] = {n="Verdammniskraut", d="Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland.", objs={"Verdammniskraut"}},
    [5501] = {n="Knochensammler", d="Bringt Bibbly F'utzbuckle bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof.", objs={"Kodoknochen"}},
    [5511] = {n="Der Schlüssel zur Scholomance"},
    [5514] = {n="Sold reimt sich auf...", d="Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan."},
    [5518] = {n="Der Ogeranzug der Gordok", d="Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", objs={"Felsteel Chest", "Gerbekorb der Oger", "Knot Thimblejacks Behälter"}},
    [5525] = {n="Befreit Knot!", d="Beute von: Schläger der Gordok, Magierlord der Gordok, Captain der Gordok", tgo={{"Schläger der Gordok", "Magierlord der Gordok", "Captain der Gordok"}}},
    [5526] = {n="Die Splitter der Teufelsranke", d="Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade."},
    [5527] = {n="Ein Reliquiar der Reinheit", d="Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück.", objs={"Staubiger Reliquienschrein"}},
    [5528] = {n="Der Gordokgeschmackstest"},
    [5529] = {n="Verseuchte Jungtiere", d="Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück.", tgo={{"Verseuchtes Jungtier"}}},
    [5534] = {n="Kim'jaels 'fehlende' Ausrüstung", d="Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jal in Azshara.", tgo={{"Sirene der Grollflossen", "Myrmidone der Grollflossen", "Kampfmeister der Grollflossen"}}},
    [5535] = {n="Spirituelle Unruhe", d="Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt.", tgo={{"Erscheinung einer Hochgeborenen"}, {"Lichling eines Hochgeborenen"}}},
    [5536] = {n="Ein Land voller Hass", d="Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zu Ashenvale zurück.", tgo={{"Satyr der Haldarr"}, {"Schwindler der Haldarr"}, {"Teufelsanbeter der Haldarr"}}},
    [5542] = {n="Dämonenhunde", d="Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Kleiner Seuchenhund"}, {"Seuchenhund"}, {"Rasender Seuchenhund"}}},
    [5543] = {n="Blutgefärbter Himmel", d="Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", tgo={{"Seuchenfledermaus"}}},
    [5544] = {n="Aassammlung", d="Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", tgo={{"Aaslarve", "Aasverschlinger"}}},
    [5561] = {n="Kodozusammentrieb", d="Bringt fünf gezähmte Kodos sowie den Kodokombobulator zu Smeed Scrabblescrew bei Scrabblescrews Lager."},
    [5581] = {n="Portale der Legion", d="Verbannt 6 Portale in Mannorocs Koven und kehrt dann zu Taiga Wisemane nach Shadowprey zurück.", tgo={{"Dämonenportalwächter"}}},
    [5601] = {n="Schwester Pamela", d="Sucht Pamela Redpath in Darrowshire."},
    [5648] = {n="Gewänder der Spiritualität", d="Findet die Grunzerin Kor'ja und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", tgo={{"Grunzer Kor'ja"}}},
    [5649] = {n="Der Spiritualität geneigt", d="Sprecht mit Tai'jin in Durotar."},
    [5650] = {n="Gewänder der Dunkelheit", d="Findet die Todeswache Kel und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryl in Brill zurück.", tgo={{"Todeswache Kel"}}},
    [5651] = {n="Der Dunkelheit geneigt", d="Sprecht mit dem Dunklen Kleriker Beryl in Tirisfal."},
    [5652] = {n="Verhexung der Schwäche"},
    [5654] = {n="Verhexung der Schwäche", d="Sprecht mit Ur'kyo in Orgrimmar."},
    [5658] = {n="Berührung der Schwäche"},
    [5679] = {n="Dunkles Opfer"},
    [5680] = {n="Schattenwache"},
    [5722] = {n="Die Suche nach dem verloren gegangenen Ranzen", d="Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen."},
    [5723] = {n="Die Kraft des Feindes wird auf die Probe gestellt", d="Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück.", tgo={{"Ragefire-Trogg"}, {"Ragefire-Schamane"}}},
    [5724] = {n="Wiederbeschaffung des verloren gegangenen Ranzens", d="Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff."},
    [5725] = {n="Die Macht der Zerstörung...", d="Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity.", tgo={{"Searingblade-Kultist", "Searingblade-Hexenmeister"}, {"Searingblade-Kultist", "Searingblade-Hexenmeister"}}},
    [5726] = {n="Verborgene Feinde", d="Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar.", tgo={{"Fanatiker der Burning Blade", "Lehrling der Burning Blade"}}},
    [5727] = {n="Verborgene Feinde", d="Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück.", tgo={{"Neeru Fireblade"}}},
    [5728] = {n="Verborgene Feinde", d="Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.", tgo={{"Bazzalan"}, {"Jergosh der Herbeirufer"}}},
    [5729] = {n="Verborgene Feinde", d="Sprecht mit Neeru Fireblade in Orgrimmar."},
    [5730] = {n="Verborgene Feinde", d="Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt."},
    [5741] = {n="Szepter des Lichts", d="Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor.", tgo={{"Seher der Burning Blade"}}},
    [5742] = {n="Erlösung", d="Hört Euch an, was Tirion Fordring zu sagen hat.", tgo={{"Tirion Fordring"}}},
    [5761] = {n="Vernichtung der Bestie", d="Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar.", tgo={{"Taragaman der Hungerleider"}}},
    [5762] = {n="Hemet Nesingwary", d="Bringt Kravels Kiste zu Hemet Nesingwary ins Schlingendorntal."},
    [5763] = {n="Jagd im Schlingendorntal", d="Bringt Roons Kodohorn zu Hemet Nesingwary ins Schlingendorntal."},
    [5781] = {n="Von vergessenen Erinnerungen", d="Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", tgo={{"Mercutio Dreckschipper"}}},
    [5802] = {n="Feuerfeder geschmiedet", d="Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.\nBringt den unvollendeten Skelettschlüssel zu Apotheker Dithers im Bollwerk, Westliche Pestländer.", objs={"Feuerfedergrat-Lavasee"}},
    [5804] = {n="Arajs Skarabäus", d="Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Dithers im Bollwerk, in den westlichen Pestländern.", objs={"Arajs Phylakterium"}},
    [5843] = {n="Willkommen!", d="Bringt Magga den 'Tal der Prüfungen'-Geschenkgutschein."},
    [5844] = {n="Willkommen!", d="Bringt Vorn Skyseer den 'Camp Narache'-Geschenkgutschein."},
    [5845] = {n="Von verlorener Ehre", d="Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", objs={"Symbol der verlorenen Ehre"}},
    [5846] = {n="Von Liebe und Familie", d="Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte."},
    [5848] = {n="Von Liebe und Familie", d="Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\nBringt das Gemälde zu Tirion Fordring.", objs={"Unvollendetes Gemälde"}},
    [5863] = {n="Das Truppenlager der Dünenbrecher", d="Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", tgo={{"Schläger der Dünenbrecher"}, {"Vollstrecker der Dünenbrecher"}, {"Gor'marok der Verheerer"}}},
    [5881] = {n="Hinzurufen der Reserve", d="Maggran möchte, dass Ihr Grish Longrunner am großen Aufzug im Brachland einen Brief zustellt."},
    [5901] = {n="Eine Plage komme über Euch", d="Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück.", objs={"Großer Termitenhügel"}},
    [5902] = {n="Eine Plage komme über Euch", d="Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen."},
    [5922] = {n="Moonglade", d="Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven."},
    [5926] = {n="Dem Ruf folgen", d="Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff."},
    [5927] = {n="Dem Ruf folgen", d="Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff."},
    [5928] = {n="Dem Ruf folgen", d="Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff."},
    [5930] = {n="Großer Bärengeist", d="Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", tgo={{"Großer Bärengeist"}}},
    [5932] = {n="Zurück nach Thunder Bluff", d="Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten."},
    [6002] = {n="Körper und Herz", d="Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\nSprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid.", tgo={{"Geist von Mondklaue"}}},
    [6022] = {n="Töten zu einem bestimmten Zweck", d="Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis."},
    [6027] = {n="Buch der Uralten", d="Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück.", tgo={{"Lord Kragaru"}}},
    [6029] = {n="Der Everlook-Bericht", d="Bringt den Everlook-Bericht zu Argentumoffizier Garush im Bollwerk in den Westlichen Pestländern."},
    [6030] = {n="Fürst Nicholas Zverenhoff", d="Bringt das Buch 'Studien zur Geistersuche' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern."},
    [6042] = {n="Die kleinen Ärgernisse des Un-Lebens", d="Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid.", tgo={{"Giftige Seuchenfledermaus"}, {"Monströse Seuchenfledermaus"}}},
    [6061] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", tgo={{"Erwachsener Ebenenschreiter"}}},
    [6062] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", tgo={{"Scheckiger Terroreber"}}},
    [6065] = {n="Der Weg des Jägers", d="Sprecht mit Yaw Sharpmane in Bloodhoof."},
    [6066] = {n="Der Weg des Jägers", d="Sprecht mit Yaw Sharpmane in Bloodhoof."},
    [6067] = {n="Der Weg des Jägers", d="Sprecht mit Yaw Sharpmane in Bloodhoof."},
    [6068] = {n="Der Weg des Jägers", d="Sprecht mit Thotar in Klingenhügel."},
    [6069] = {n="Der Weg des Jägers", d="Sprecht mit Thotar in Klingenhügel."},
    [6070] = {n="Der Weg des Jägers", d="Sprecht mit Thotar in Klingenhügel."},
    [6081] = {n="Die Ausbildung des Tiers", d="Sprecht mit Ormak Grimshot in Orgrimmar."},
    [6082] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", tgo={{"Gepanzerter Skorpid"}}},
    [6083] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", tgo={{"Brandungskriecher"}}},
    [6087] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", tgo={{"Präriepirscher"}}},
    [6088] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", tgo={{"Sturzflieger"}}},
    [6089] = {n="Die Ausbildung des Tiers", d="Sprecht mit Holt Thunderhorn auf der Anhöhe der Jäger in Thunder Bluff."},
    [6126] = {n="Neue Lektionen", d="Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven."},
    [6127] = {n="Die eigentliche Ursache", d="Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.\nBringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runetotem in Crossroads im Brachland.", objs={"Dreadmist Peak Pool"}},
    [6128] = {n="Das Heilmittel sammeln", d="Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runetotem in Crossroads, damit er eine Heilsalbe machen kann.", tgo={{"Wildschlagsetzling", "Zornranke"}, {"Verirrter Brachlandkodo", "Brachlandkodo"}}},
    [6129] = {n="Heilung der Kranken", d="Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße durch Crossroads gesehen.", tgo={{"Kränkliche Gazelle"}}},
    [6130] = {n="Macht über Gift", d="Kehrt zu Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff zurück."},
    [6134] = {n="Geisterplasmasuche", d="Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brimbuzzle in Desolace.", tgo={{"Zentaurengeist"}}},
    [6142] = {n="Muschelköder", d="Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Shadowprey.", tgo={{"Wütender Riffkriecher"}}},
    [6143] = {n="Andere Fische zu grillen", d="Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberhexerinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Shadowprey.", tgo={{"Myrmidone der Zackenkämme"}, {"Naga der Zackenkämme"}, {"Zauberhexerin der Zackenkämme"}}},
    [6161] = {n="Nehmt Rackmores Schatz!", d="Sucht Rackmores Silberschlüssel. Sucht Rackmores Goldschlüssel. Sucht und öffnet Rackmores Truhe.", tgo={{"Kaltschnappkriecher", "Kaltschnappzange"}, {"Naga der Zackenkämme", "Zauberhexerin der Zackenkämme", "Krieger der Zackenkämme"}}},
    [6162] = {n="Eines Ehemanns letzter Kampf", d="Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald.", tgo={{"Oberanführer Ror"}}},
    [6164] = {n="Augustus' Rezeptbuch", d="Bringt Augustus' Quittungsbuch zu Augustus dem Meschuggenen im Schreckenstal.", objs={"Augustus' Rezeptbuch"}},
    [6282] = {n="Harpyien drohen", d="Maggran Earthbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", tgo={{"Harpyie der Blutfurien"}, {"Wegelagerin der Blutfurien"}, {"Töterin der Blutfurien"}, {"Wildfeder der Blutfurien"}}},
    [6283] = {n="Blutfuriengeschlecht", d="Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.", tgo={{"Zerfetzerin der Blutfurien"}}},
    [6284] = {n="Arachnophobie", d="Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels.", tgo={{"Besseleth"}}},
    [6301] = {n="Zyklus der Wiedergeburt", d="Tammra Windfield in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.", objs={"Gaeasamenkorn"}},
    [6381] = {n="Neues Leben", d="Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und sprecht dann mit Tammra in Sonnenfels.", objs={"Gaeaerdhügel"}},
    [6382] = {n="Die Jagd in Ashenvale", d="Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale."},
    [6383] = {n="Die Jagd in Ashenvale"},
    [6390] = {n="Eine Plage komme über Euch", d="Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück."},
    [6393] = {n="Krieg der Elementare", d="Bringt 10 Pyrophore zu Tsunaman in Sonnenfels.", tgo={{"Wilder Flammengeist", "Brennender Verheerer", "Brennender Zerstörer"}}},
    [6394] = {n="Thazz'rils Hacke", d="Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", objs={"Thazz'rils Hacke"}},
    [6395] = {n="Marlas letzter Wunsch", d="Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück.", objs={"Marlas Grab"}},
    [6421] = {n="Steinschlagklamm", d="Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.", objs={"Resonitkristall"}},
    [6441] = {n="Satyrhörner", d="Sammelt für Pixel im Splintertreeposten 16 Satyrhörner.", tgo={{"Schurke von Xavian", "Verräter von Xavian", "Teufelsanbeter von Xavian"}}},
    [6442] = {n="Die Naga am Zoramstrand", d="Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen.", tgo={{"Myrmidone der Rächerflossen", "Klingenschwanz der Rächerflossen", "Wellenreiter der Rächerflossen"}}},
    [6461] = {n="Blutfresser", d="Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet.", tgo={{"Kluftmooskrabbler"}, {"Kluftmoosgiftspucker"}}},
    [6462] = {n="Troll-Glücksbringer", d="Bringt Mitsuwa im Zoram'gar-Außenposten 8 Troll-Glücksbringer.", objs={"Trolltruhe"}},
    [6481] = {n="Der Irdene erhebt sich", d="Öffnet das Resonitfässlein mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück.", tgo={{"Goggeroc"}}},
    [6482] = {n="Freiheit für Ruul", d="Begleitet Ruul und sprecht dann mit Yama Snowhoof im Splintertreeposten."},
    [6503] = {n="Die Kundschafter von Ashenvale", d="Tötet 9 Kundschafter von Ashenvale und kehrt dann zu Kuray'bin im Splintertreeaußenposten zurück.", tgo={{"Kundschafter von Ashenvale"}}},
    [6504] = {n="Die verlorenen Seiten", d="Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen."},
    [6521] = {n="Eine unheilige Allianz", d="Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity.", tgo={{"Botschafter Malcin"}}},
    [6522] = {n="Eine unheilige Allianz", d="Bringt die kleine Rolle zu Varimathras nach Undercity."},
    [6541] = {n="Meldung bei Kadrak", d="Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak."},
    [6543] = {n="Die Warsongberichte", d="Bringt die Warsongberichte dem Warsongspäher, dem Warsongläufer und der Warsongvorhut. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands."},
    [6544] = {n="Toreks Angriff", d="Eskortiert Torek bei seinem Angriff auf den Außenposten der Silverwing und Duriel Moonfire. Erstattet dann Ertog Ragetusk im Splintertreeposten Bericht."},
    [6545] = {n="Warsongläufer-Update"},
    [6546] = {n="Warsongvorhut-Update"},
    [6547] = {n="Warsongspäher-Update"},
    [6561] = {n="Blackfathom-Schurkerei", d="Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff.", tgo={{"Twilight-Lord Kelris"}}},
    [6562] = {n="Ärger in der Tiefe", d="Sprecht in Ashenvale mit Je'neu Sancrea."},
    [6563] = {n="Die Essenz von Aku'mai", d="Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale.", objs={"Saphir von Aku'Mai"}},
    [6564] = {n="Treue zu den Alten Göttern", d="Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale."},
    [6565] = {n="Treue zu den Alten Göttern", d="Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück.", tgo={{"Lorgus Jett"}}},
    [6621] = {n="König der Fäulnisklauen", d="Platziert Karangs Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Karang Amakkar in Zoram'gar.", tgo={{"Häuptling Murgut"}}},
    [6626] = {n="Ein Hort des Bösen", d="Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück.", tgo={{"Schlachtwache von Razorfen"}, {"Dornenwirker von Razorfen"}, {"Kultistin der Totenköpfe"}}},
    [6627] = {n="Test der Lehre", d="Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid."},
    [6641] = {n="Vorsha die Peitscherin", d="Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft.\nWenn Ihr erfolgreich gewesen seid, kehrt zum Zoram'garposten zurück und informiert den Warsongläufer über den Tod von Vorsha der Peitscherin."},
    [6681] = {n="Das Anwesen, Ravenholdt", d="Bringt das Ravenholdt-Siegel zu Fahrad im Ravenholdt-Anwesen, das versteckt in den Hügeln von Hillsbrad liegt.\nUnterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.", tgo={{"Ravenholdt"}}},
    [6701] = {n="Syndikatsembleme", d="Beute von: Auftragsmörder des Syndikats, Herbeizauberer des Syndikats, Schleicher des Syndikats", tgo={{"Auftragsmörder des Syndikats", "Herbeizauberer des Syndikats", "Schleicher des Syndikats"}}},
    [6844] = {n="Umber, Archivar", d="Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nighthaven in Moonglade."},
    [6845] = {n="Enthüllung von Geheimnissen der Vergangenheit", d="Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade."},
    [6921] = {n="Inmitten der Ruinen", d="Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", objs={"Fathom-Stein"}},
    [6922] = {n="Baron Aquanis", d="Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."},
    [6981] = {n="Der leuchtende Splitter", d="Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.\nLiefert dann den Splitter ab, wie Ihr angewiesen wurdet.", tgo={{"Sputtervalve"}}},
    [7003] = {n="Geschrumpfte Riesen", d="Benutzt Zorbins Super-Schrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin Fandazzle 15 Schrumpf-Überreste von diesen Riesen. Ihr findet ihn bei den Docks, an der vergessenen Küste in Feralas.", tgo={{"Landgänger", "Klippenriese", "Uferschreiter"}}},
    [7028] = {n="Dunkles Böses", d="Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace.", tgo={{"Verfluchter Zentaur", "Satyr der Putridus", "Schwindler der Putridus"}}},
    [7029] = {n="Schlangenzunges Verderbnis", d="Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.\nHeilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Vark Battlescar in Shadowprey zurück.", tgo={{"Noxxious-Spross"}, {}}, objs={"Maraudon orangefarbenen Kristallteich"}},
    [7044] = {n="Legenden von Maraudon", d="Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.\nFindet einen Weg, um mit Celebras zu sprechen.", tgo={{"Lord Schlangenzunge"}, {"Noxxion", "Noxxions Brut"}}},
    [7046] = {n="Das Szepter von Celebras", d="Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.\nSprecht mit ihm, nachdem das Ritual vollendet ist.", objs={"Incantation of Celebras"}},
    [7064] = {n="Verderbnis von Erde und Samenkorn", d="Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück.", tgo={{"Prinzessin Theradras"}}},
    [7066] = {n="Samenkorn des Lebens", d="Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens."},
    [7067] = {n="Die Anweisungen des Pariahs", d="Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace."},
    [7068] = {n="Schattensplitter", d="Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar.", tgo={{"Schattensteinrumpler", "Schattensteinzerkracher", "Schattensteindonnerer"}}},
    [7201] = {n="Das letzte Element", d="Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hin gemurmelt hat.", tgo={{"Geschmolzener Kriegsgolem", "Wuthäschergolem", "Kriegshetzerkonstrukt"}}},
    [7441] = {n="Pusillin und der Älteste Azj'Tordin", d="Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.\nKehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück.", tgo={{"Pusillin"}}},
    [7461] = {n="Der innere Wahnsinn", d="Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", tgo={{"Immol'thar"}, {"Prinz Tortheldrin"}}},
    [7463] = {n="Arcane Erfrischung", d="Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück.", tgo={{"Hydrobrut"}}},
    [7481] = {n="Elfische Legenden", d="Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache.", objs={"Die sterblichen Überreste von Telmius Dreamseeker"}},
    [7489] = {n="Lethtendris' Netz", d="Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas.", tgo={{"Lethtendris"}}},
    [7492] = {n="Camp Mojache", d="Sprecht mit Talo Thornhoof in Camp Mojache, in Feralas."},
    [7498] = {n="Garona: Eine Studie über Heimlichkeit und Verrat", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7499] = {n="Kodex der Verteidigung", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7500] = {n="Das Arkanistenkochbuch", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7501] = {n="Vom Licht und wie man es schwingt", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7502] = {n="Schatten einspannen", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7503] = {n="Das größte Volk von Jägern", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7504] = {n="Heiliger Fleischklops: Was das Licht Dir nicht erzählt", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7505] = {n="Frostschock und Du", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7506] = {n="Der Smaragdgrüne Traum", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7601] = {n="Nibys Anweisungen", d="Sprecht mit Impsy im Teufelswald."},
    [7602] = {n="Reine Teufelsessenz", d="Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.\nDie Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den verwüsteten Landen bergen die Teufelsessenz ihrer Region.\nFindet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald.", tgo={{"Satyr der Legashi", "Schurke der Legashi", "Höllenrufer der Legashi"}, {"Legionär von Jaedenar"}, {"Wachposten der Teufelswache"}}},
    [7603] = {n="Kroshius Höllenbestienkern", d="Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.\nBringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="GESUCHT: Vorarbeiter Maltorius", d="Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.\nTötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Ausguck Captain Lolo Longstriker in der sengenden Schlucht für eine Belohnung.", tgo={{"Aufseher Maltorius"}}},
    [7721] = {n="Treibstoff fürs Schrumpfen", d="Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin Fandazzle in der Nähe des dortigen Docks.", tgo={{"Meereselementar", "Meeresschauer"}}},
    [7722] = {n="Was zum Fluxus?!", d="Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht.", objs={"Geheimpläne: Feuriger Fluxus"}},
    [7723] = {n="Verdammt seien diese fetten Finger", d="Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet.\nDie Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", tgo={{"Schwerer Kriegsgolem"}}},
    [7724] = {n="Feurige Bedrohung!", d="Hansel Heavyhands möchte, dass Ihr 20 sengende Lavaspinnen in der sengenden Schlucht tötet.\nDie sengenden Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der sengenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", tgo={{"Versengende Lavaspinne"}}},
    [7727] = {n="Incendosaurier? Was-auch-immer-Saurier?", d="Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet.\nDie Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der segenden Schlucht.\nSobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Heavyhands in der sengenden Schlucht zurück.", tgo={{"Incendosaurier"}}},
    [7728] = {n="GESTOHLEN: Schmiedewindform und ein Ausguck-Handfernrohr", d="Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht.\nDie einzigen Informationen die Ihr habt sind: Die Schmiedewindform is ein SCHMIEDEwerkzeug welches von SCHMIEDEN verwendet wird und das Ausguck-Handfernrohr ist ein unverzichtbares Werkzeug für SPÄHPOSTEN.", tgo={{"Dampfschmied der Dunkeleisenzwerge"}, {"Ausguck der Dunkeleisenzwerge"}}},
    [7729] = {n="STELLE ZU VERGEBEN: Erledige die Konkurrenz", d="Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Zuchtmeister der Dunkeleisenzwerge"}, {"Sklavenhändler der Dunkeleisenzwerge"}}},
    [7730] = {n="Zukk'ash-Plage", d="Bringt Hadoken Swiftstrider im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer.", tgo={{"Stecher der Zukk'ash", "Wespe der Zukk'ash", "Arbeiter der Zukk'ash"}}},
    [7731] = {n="Zornstachel", d="Besiegt Zornstachel in der verwundenen Tiefe und bringt seine Drüsen zu Hadoken Swiftstrider im Camp Mojache in Feralas zurück.", tgo={{"Zornstachel"}}},
    [7732] = {n="Bericht über die Zukk'ash", d="Bringt den Bericht über die Zukk'ash aus Camp Mojache zu Zilzibin Drumlore. Er wohnt in der Gasse von Orgrimmar."},
    [7734] = {n="Beste Qualität", d="Bringt Jangdor Swiftstrider im Camp Mojache in Feralas 10 Wutschrammyetibälge.", tgo={{"Wutschrammyeti", "Alter Wutschrammyeti", "Wilder Wutschrammyeti"}}},
    [7738] = {n="Perfekter Yetibalg", d="Bringt Jangdor Swiftstrider im Camp Mojache in Feralas den makellosen Yetibalg."},
    [7761] = {n="Blackhands Befehl", d="Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.\nDem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen."},
    [7815] = {n="Schnappkiefer, Alter!", d="Katoom, der Angler aus Revantusk im Hinterland möchte, dass Ihr 15 Salzwasserschnappkiefer-Schildkröten tötet. Kehrt zu Ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", tgo={{"Salzwasserschnappkiefer"}}},
    [7816] = {n="Gammerita, Alter!", d="Katoom, der Angler aus Revantusk im Hinterland möchte, dass Ihr Gammerita tötet und Katooms besten Köder aus ihrem Kadaver holt.\nKatoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.", tgo={{"Gammerita"}}},
    [7828] = {n="Die Pirsch auf die Pirscher", d="Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 15 Silbermähnenpirscher und 15 Silbermähnenheuler tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.\nMarkhor erwähnte, dass sich die Wölfe in der Wildnis des Hinterlands verstecken.", tgo={{"Silbermähnenpirscher"}, {"Silbermähnenheuler"}}},
    [7829] = {n="Jagt die Wilden", d="Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 20 Wilde Eulenbestien tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.\nMarkhor erwähnte, dass sich die Eulenbestien in der Wildnis des Hinterlands befinden.", tgo={{"Wilde Eulenbestie"}}},
    [7830] = {n="Die Gefallenen rächen", d="Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr einen Klingenschnabelhimmelsfürsten tötet und dessen Federbusch an Euch nehmt. Kehrt zu ihm zurück sobald Ihr diese Aufgabe erledigt habt.\nDie Klingenschnabelhimmelsfürsten sind eine recht seltene Spezies und nisten meist in der Wildnis des Hinterlands.", tgo={{"Klingenschnabelhimmelsfürst"}}},
    [7839] = {n="Schläger der Vilebranch", d="Schmied Slagtree aus Revantusk im Hinterland möchte, dass Ihr seine verlorenen Werkzeuge ausfindig macht und dann zu ihm zurückkehrt.\nIhr erinnert Euch an Schmied Slagtrees Worte, dass die Werkzeuge möglicherweise bei einem der Tempel der Vilebranch zu finden seien, im Nordosten des Hinterlands. Ihr solltet auch Skulk Rock absuchen.", objs={"Slagtrees verlorene Werkzeuge"}},
    [7840] = {n="Lards vergessene Brotzeit", d="Lard aus Revantusk im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Vilebranch.", tgo={{"Kidnapper der Vilebranch"}}},
    [7845] = {n="Die Entführung des Älteren Torntusk", d="Primal Torntusk aus Raventusk im Hinterland möchte, dass Ihr ihren Gefährten, den Älteren Torntusk, aus Jintha'Alor befreit.\nMan sagte Euch, dass er hoch oben in Jintha'Alor gefangen gehalten wird - der Hauptstadt der Vilebranch im Süden des Hinterlands."},
    [7846] = {n="Erlangt den Schlüssel!", d="Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Hitah'ya die Bewahrerin tötet, um in den Besitz des Fesselnschlüssels zu kommen. Kehrt zum Älteren Torn'tusk zurück, wenn Ihr den Schlüssel habt.", tgo={{"Hitah'ya die Bewahrerin"}}},
    [7847] = {n="Rückkehr zu Primal Torntusk", d="Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Primal Torntusk in Revantusk die Neuigkeit von seiner Befreiung überbringt."},
    [7848] = {n="Abstimmung mit dem Kern", d="Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück.", objs={"Kernfragment"}},
    [7849] = {n="Die getrennten Brüder", d="Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr die Überreste seines Zwillingsbruders bergt. Findet den Schädel und die Knochen des Jägers Malkhor und bringt sie zu Jäger Markhor zurück.\nMarkhor erwähnte, dass die Überreste seines Bruders an die Brühschlammer und Wölfe der Vilebranch verfüttert wurden. Er sagte weiterhin, dass es in Jintha'Alor eine Grube mit Brühschlammern gibt, sowie einen Wolfsbau. Beide liegen in der Nähe der Tempelspitze.", objs={"Schädelhaufen", "Knochenhaufen"}},
    [7850] = {n="Dunkle Gefäße", d="Primal Torntusk aus Revantusk im Hinterland möchte, dass Ihr Euch 10 Gefäße mit besudeltem Blut aus Jintha'Alor beschafft. Kehrt dann damit zu Primal Torntusk zurück.", objs={"Gefäß mit besudelten Blut"}},
    [7861] = {n="GESUCHT: Üble Priesterin Hexx und ihre Diener", d="Ihr habt die Anweisung erhalten die üble Priesterin Hexx und 20 Aman'zasiwachen der Vilebranch zu töten. Habt Ihr Eure Aufgabe erfüllt, so sprecht mit Primal Torntusk aus Revantusk im Hinterland.\nDie üble Priesterin Hexx und die Aman'zasiwachen halten sich hoch oben in Jintha'Alor im Hinterland auf.", tgo={{"Üble Priesterin Hexx"}, {"Aman'zasiwache der Vilebranch"}}},
    [7862] = {n="Offener Posten: Wachbefehlshaber von Revantusk", d="Ihr wurdet mit der Vernichtung von 20 Berserkern der Vilebranch, 20 Schattenjägern der Vilebranch, 20 Bluttrinkern der Vilebranch und 20 Seelenfressern der Vilebranch beauftragt.\nKehrt nach Beendigung dieser Aufgabe zu Primal Torntusk aus Revantusk im Hinterland zurück.", tgo={{"Berserker der Vilebranch"}, {"Schattenjäger der Vilebranch"}, {"Bluttrinker der Vilebranch"}, {"Seelenfresser der Vilebranch"}}, star={"Rune des Wachbefehlshabers", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="Der Schatz der Shen'dralar", d="Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!"},
    [8151] = {n="Der Talisman des Jägers", d="Sprecht mit Ogtinc in Azshara."},
    [8153] = {n="Gehörnte Renner", d="Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath.", tgo={{"Mooshufrenner"}}},
    [8231] = {n="Wellenjagd", d="Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", tgo={{"Junger Wellenhauer", "Wellenhauer", "Großer Wellenhauer"}}},
    [8232] = {n="Der grüne Drache", d="Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", tgo={{"Morphaz"}}, star={"Auge eines Teufelssauriers", {"HUNTER"}}},
    [8233] = {n="Ein simples Anliegen", d="Sprecht mit Lord Jorach Ravenholdt im Ravenholdt-Anwesen."},
    [8234] = {n="Die versiegelte azurblaue Tasche", d="Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist.", tgo={{"Schamane der Holzschlundfeste", "Schamane des Schwarzschlunds"}}},
    [8235] = {n="Verschlüsselte Fragmente", d="Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente.", tgo={{"Waldbrühschlammer"}}},
    [8236] = {n="Der azurblaue Schlüssel", d="Bringt den azurblauen Schlüssel zu Lord Jorach Ravenholdt.", tgo={{"Morphaz"}}, star={"Nachtsaugertuch", {"ROGUE"}}},
    [8250] = {n="Geschick der Magier", d="Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem."},
    [8251] = {n="Magischer Staub", d="Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben.", tgo={{"Blutelfenfeldmesser", "Blutelfenwiederbeschafferin", "Blutelfenverteidiger"}}},
    [8252] = {n="Die Koralle der Sirenen", d="Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem.", tgo={{"Sirene der Grollflossen"}}},
    [8253] = {n="Vernichtet Morphaz", d="Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", tgo={{"Morphaz"}}, star={"Feuerrubin", {"MAGE"}}},
    [8254] = {n="Cenarische Hilfe", d="Sucht Ogtinc in Azshara auf."},
    [8255] = {n="Renner für einen höheren Zweck", d="Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", tgo={{"Mooshufrenner"}}},
    [8256] = {n="Sekret des Untodes", d="Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", tgo={{"Zombie von Zanzil", "Jäger von Zanzil", "Skelettschinder"}}},
    [8257] = {n="Morphaz' Blut", d="Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends.", tgo={{"Morphaz"}}, star={"Gesegnete Gebetsperlen", {"PRIEST"}}},
    [8276] = {n="Die Rückeroberung von Silithus", d="Sprecht mit Windruferin Proudhorn auf Burg Cenarius in Silithus."},
    [8277] = {n="Tödliches Wüstengift", d="Beetix Ficklespragg von der Burg Cenarius in Silithus möchte, dass Ihr 8 Stachel von Steinpanzerskorpiden und 8 Giftzähne von Sandhuschern für sie sammelt. Kehrt zu ihr zurück, sobald Ihr diese Aufgabe erfüllt habt.", tgo={{"Steinpanzerskorpid"}, {"Sandhuscher"}}},
    [8278] = {n="Noggles letzte Hoffnung", d="Beetix Ficklespragg von der Burg Cenarius in Silithus möchte, dass Ihr je 3 Stachel von Steinpanzerzangen und Steinpanzerschindern, sowie 3 Felspirschergiftzähne für sie sammelt.", tgo={{"Steinpanzerschinder"}, {"Steinpanzerzange"}, {"Felspirscher"}}},
    [8280] = {n="Sicherung der Versorgungslinien", d="Windruferin Proudhorn auf Burg Cenarius in Silithus möchte, dass Ihr 15 Baggerschläger tötet.", tgo={{"Baggerschläger"}}},
    [8281] = {n="Verstärkte Sicherheit", d="Windruferin Proudhorn auf Burg Cenarius in Silithus möchte, dass Ihr 20 Baggerbrecher tötet.", tgo={{"Baggerbrecher"}}},
    [8284] = {n="Das Geheimnis der Twilight-Hammer", d="Geologin Larksbane auf Burg Cenarius möchte, dass Ihr ihr 8 Schrifttafelfragmente der Twilight bringt.", objs={"Schrifttafelfragment der Twilight"}},
    [8285] = {n="Der Deserteur", d="Bringt die wiederhergestellte Schrifttafel zu Ortell dem Einsiedler in Silithus."},
    [8318] = {n="Geheime Nachrichten", d="Bringt Bor Wildmane auf Burg Cenarius 10 verschlüsselte Texte der Twilight.", tgo={{"Bewahrer der Twilight Havunth", "Rächer der Twilight", "Geolord der Twilight"}}},
    [8365] = {n="Piratenhüte Ahoy!", d="Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin nach Steamwheedle in Tanaris.", tgo={{"Pirat der Südmeerfreibeuter", "Seeräuber der Südmeerfreibeuter", "Dockarbeiter der Südmeerfreibeuter"}}},
    [8366] = {n="Gaunerei und Erpressung im Südmeer", d="Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris beauftragt Euch, 10 Piraten der Südmeerfreibeuter, 10 Seeräuber der Südmeerfreibeuter, 10 Dockarbeiter der Südmeerfreibeuter und 10 Schwadroneure der Südseefreibeuter zu töten.", tgo={{"Pirat der Südmeerfreibeuter"}, {"Seeräuber der Südmeerfreibeuter"}, {"Dockarbeiter der Südmeerfreibeuter"}, {"Schwadroneur der Südmeerfreibeuter"}}},
    [8411] = {n="Die Beherrschung der Elemente", d="Bringt Bath'rah dem Windbehüter die Elemente Erde, Luft, Feuer und Wasser.", tgo={{"Staubteufel", "Donnernder Verbannter", "Cyclonian"}, {"Felselementar", "Steinwüter", "Elementarsklave"}, {"Botschafter Infernus", "Brennender Verbannter", "Wilder Flammengeist"}, {"Geringer Wasserelementar", "Schäumender Verbannter", "Beschworener Wächter"}}},
    [8412] = {n="Geistertotem", d="Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem.", tgo={{"Aasgeier", "Aaslauerer", "Giftnebellauerer"}, {"Aasgeier", "Kranker Schwarzbär", "Kranker Grizzly"}}},
    [8413] = {n="Die Macht des Voodoos", d="Bringt Bath'rah dem Windbehüter die Voodoofedern.", tgo={{"Schlitzer", "Zul'Lor", "Schlitzer"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}, star={"Entzückter Wassergeist", {"SHAMAN"}}},
    [8417] = {n="Ein geplagter Geist", d="Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen."},
    [8420] = {n="Heiß und brennend", d="Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", tgo={{"Teufelsjäger", "Wachposten der Teufelswache", "Satyr der Legashi"}}},
    [8421] = {n="Das richtige Zeug", d="Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald.", tgo={{"Wanderer der Eisenstämme", "Donnerstampfer der Eisenstämme", "Siechender Beschützer"}, {"Besudelter Brühschlammer"}}},
    [8422] = {n="Federn von Trollen", d="Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel.", tgo={{"Schlitzer", "Zul'Lor", "Schlitzer"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}, star={"Seelenernter", {"WARLOCK"}}},
    [8423] = {n="Kriegerverwandtschaft", d="Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.", tgo={{"Hölleneber"}}},
    [8424] = {n="Krieg den Schattenanbetern", d="Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.", tgo={{"Adept der Schattenanbeter"}, {"Kultist der Schattenanbeter"}, {"Rohling der Schattenanbeter"}}},
    [8425] = {n="Voodoofedern", d="Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde.", tgo={{"Schlitzer", "Zul'Lor", "Schlitzer"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}, star={"Diamantenfläschchen", {"WARRIOR"}}},
    [8460] = {n="Verbündeter der Holzschlundfeste", d="Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt.", tgo={{"Krieger der Totenwaldfelle"}, {"Pfadfinder der Totenwaldfelle"}, {"Gärtner der Totenwaldfelle"}}},
    [8461] = {n="Totenwaldfelle des Nordens", d="Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.", tgo={{"Höhlenbehüter der Totenwaldfelle"}, {"Rächer der Totenwaldfelle"}, {"Schamane der Totenwaldfelle"}}},
    [8462] = {n="Sprecht mit Nafien", d="Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg names Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache."},
    [8464] = {n="Aktivität der Winterfelle", d="Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich direkt außerhalb des Eingangs zur Holzschlundfeste in Winterspring.", tgo={{"Schamane der Winterfelle"}, {"Höhlenbehüter der Winterfelle"}, {"Ursa der Winterfelle"}}},
    [8465] = {n="Sprecht mit Salfa", d="Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterspring. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht."},
    [8551] = {n="Die Truhe des Kapitäns", d="Bringt Smotts' Truhe zu Hecklebury Smotts nach Booty Bay.", tgo={{"Gorlash"}}},
    [9051] = {n="Giftexperiment", d="Stecht einen Teufelssaurier mit dem Teufelssaurierhaken."},
    [9052] = {n="Blutblütengift", d="Sammelt Blutkappenpilze und Gorishistachel und kehrt zu Torwa Pathfinder im Un'Goro Krater zurück.", tgo={{"Wespe der Gorishi", "Stecher der Gorishi"}, {}}, objs={"Blutblütensprössling"}},
    [9053] = {n="Eine bessere Zutat", d="Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des versunkenen Tempels und kehrt zu Torwa Pathfinder zurück.", tgo={{"Atal'alarion"}}, star={"Ergrauter Pelz", {"DRUID"}}},
    [65593] = {n="Herzen der Liebenden", d="Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten.", tgo={{"Avelina Lilly"}, {"Isaac Pearson"}}},
    [65597] = {n="Die Bindung", d="Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Undercity zurück.", tgo={{"Beschworener Inkubus"}}},
    [65601] = {n="Liebe kann schmerzhaft sein", d="Sprecht mit Magar in Orgrimmar."},
    [65604] = {n="Die Bindung", d="Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Bloodeye in Orgrimmar zurück.", tgo={{"Beschworener Inkubus"}}},
    [65610] = {n="Irgendwo anders", d="Untersucht den Fallenskysee in Ashenvale und erstattet Gan'rul Bloodeye in Orgrimmar Bericht.", tgo={{"Schattendickichtsteinrücker", "Schattendickichtborkenreißer", "Schattendickichtorakel"}}},
    [78261] = {n="Das Horn von Xelthos", d="Findet das Horn von Xelthos in der Burg Schattenfang. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen."},
    [78270] = {n="Goblinischer Schlossknacker", d="Beute von: Roder der Venture Co., Maschinenführer der Venture Co., Holzarbeiter der Venture Co.", tgo={{"Roder der Venture Co.", "Maschinenführer der Venture Co.", "Holzarbeiter der Venture Co."}}},
    [78307] = {n="Das Horn von Xelthos", d="Log"},
    [78676] = {n="Das Auge von Bhossca", d="Findet das Auge von Bhossca im Scharlachroten Kloster. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen.", objs={"Verschlossenes Reliquiar"}},
    [78699] = {n="Das Auge von Bhossca", d="Log"},
    [78830] = {n="Schrecken des Wüstenhimmels", d="Holt Euch eine blutrote Trophäenfeder von Gharrik im Ödland. Kehrt anschließend zu Hemet Nesingwary im Schlingendorntal zurück.", tgo={{"Gharrik"}}},
    [79229] = {n="Straßenraub", d="Findet jemanden in Desolace, der etwas über das geplünderte Lager weiß."},
    [79235] = {n="Auf der Flucht", d="Findet einen der Plünderer von Desolace."},
    [79236] = {n="Eine Kirsche für Eure Gedanken", d="Bringt einen Kirschgrog zu Tokal in Booty Bay, um den Rest ihrer Geschichte zu hören."},
    [79360] = {n="Elementare Hilfe", d="Besiegt Charlga Razorflank im Kral von Razorfen und sammelt Informationen über die Pläne der Stacheleber.", tgo={{"Charlga Razorflank"}}},
    [79361] = {n="Sturm, Erde und Feuer", d="Sammelt 5 verdrehte Feuertotems, 5 verdrehte Erdtotems, 5 verdrehte Lufttotems und 5 verdrehte Wassertotems für Prate Cloudseer in Tausend Nadeln.", tgo={{"Pfützenspringer der Schlammflossen", "Murloc der Schlammflossen", "Krieger der Schlammflossen"}, {"Matschlauerer der Verirrten", "Angler der Verirrten", "Jäger der Verirrten"}, {"Schädelhauer der Steingrufttroggs", "Knochenknacker der Steingrufttroggs", "Schamane der Steingrufttroggs"}, {"Zänker der Maraudine", "Raufer der Maraudine", "Windhetzer der Maraudine"}}},
    [79364] = {n="Blick zum Himmel", d="Sprecht mit Prate Cloudseer in Tausend Nadeln."},
    [79365] = {n="Mit Wind unter Euren Schwingen", d="Kehrt zu Rau Cliffrunner im Freiwindposten in Tausend Nadeln zurück."},
    [79366] = {n="Hört meinen Ruf", d="Verwendet die verdrehten Totems, um das Stacheleberritual ein für alle mal zu beenden.", tgo={{"Tobender Gewittersturm"}}},
    [79442] = {n="Die Waffen des Sturmgewitters", d="Bringt das Auge des Gewittersturms zu Bath'rah dem Windbehüter im Alteracgebirge.", star={"Wut des Sturms / Griff des Blitzschlags / Klaue des Gezeitenbringers"}},
    [80411] = {n="Der Talisman von Kazdor", d="Findet den Talisman von Kazdor in Zul'Farrak. Bringt ihn anschließend zu Fahrad im Ravenholdt-Anwesen. Ihr müsst diese Aufgabe alleine erledigen.", objs={"Verzauberte Kriegstruhe"}},
    [80526] = {n="Schande über mich", d="Sprecht mit Fahrad, wenn Ihr bereit seid, seinen Plan anzuhören."},
    [82084] = {n="Eine Lektion in Sachen Schriftkundigkeit", d="Macht die Zauberbuchmaterialien, die der Bibliothekar angefordert hat, ausfindig und sammelt sie ein.", tgo={{"Heimtückische Eulenbestie", "Primitive Eulenbestie", "Wilde Eulenbestie"}, {"Stecher der Zukk'ash", "Wespe der Zukk'ash", "Arbeiter der Zukk'ash"}, {"Zombie aus Zul'Farrak"}}},
    [84398] = {n="Eine Studie des Lichts", d="Benutzen/Sammeln: Buch", objs={"Buch"}},
    [86576] = {n="Blutfurienzierrat", d="Bringt Mor'rogal 15 glitzernde Sonnensteine.", tgo={{"Harpyie der Blutfurien", "Wildfeder der Blutfurien", "Töterin der Blutfurien"}}},
    [90902] = {n="Das Licht wiederentdecken", d="Heal 5 verletzte Todeswachen mit Eurer Fähigkeit 'Heiliges Licht'.", tgo={{"Verletzte Todeswache"}}},
    [91208] = {n="Trauerbewältigung", d="Findet den verängstigten Paladin in Deathknell.", tgo={{"Verängstigter Paladin"}}},
    [91209] = {n="Setzt Eure Ausbildung fort", d="Folgt der Straße nach Osten aus Deathknell heraus, um nach Brill zu gelangen. Meldet Euch bei Shari Stilwell, um Eure Ausbildung fortzusetzen.", tgo={{"Shari Stilwell"}}},
    [91282] = {n="Ein zweites Zuhause", d="Findet die Bandarionfestung und meldet Euch dort bei Brenton Samuels."},
    [91285] = {n="Murlocs vor der Toren", d="Tötet 8 Angreifer der Finsterflossen und 8 Seher der Finsterflossen und erstattet Brenton Samuels nach getaner Arbeit Bericht.", tgo={{"Angreifer der Finsterflossen"}, {"Seher der Finsterflossen"}}},
    [91294] = {n="Ein Rundgang durch die Anlage", d="Sprecht mit den Einwohnern der Bandarionfestung.", tgo={{"Hilda die Brecherin"}, {"Jorin Croge"}, {"Ander Solliden"}, {"Danitha Morr"}}},
    [91316] = {n="Reparaturen", d="Sammelt 12 Stück stabiles Bauholz aus Schattental in Tirisfal.", objs={"Holzstapel"}},
    [91317] = {n="Der Befleckte", d="Tötet 8 befleckte Akkordarbeiter sowie 6 befleckte Fanatiker und holt Euch den Kopf von Kommandant Rudolph Gelhardt in Tirisfal.", tgo={{"Rudolph Gelhardt"}}},
    [91497] = {n="Siegel der Sin'dorei", d="Bringt das Siegel des Wächters, das Siegel des Kriegers und das Siegel des Waldläufers zum Sin'doreifoliant der Beschwörung.", tgo={{"Leutnant Suncrest"}, {"Magistrix Falkhelm"}, {"Waldläuferin Lydrea"}}},
    [91500] = {n="Ein explosiver Schachzug", d="Zerstört die Siegel der Sin'dorei und bringt dann Magus Rimtoris Kopf zu Ag'tor Bloodfist in Valormok.", tgo={{"Magus Rimtori"}}},
    [91531] = {n="Rache genommen", d="Bringt den Kopf von Magus Rimtori zu Belgrom Rockmaul in Orgrimmar."},
    [91858] = {n="Diplomatischer Zwischenfall", d="Reist zum Grabmal im Silberwald und sprecht mit Trevan Rol über die vermissten Reisenden des Irdenen Rings."},
    [91859] = {n="Ein seltsames Paar", d="Sprecht mit Todeswache Baldren über die mysteriösen Reisenden des Irdenen Rings, die kürzlich durch das Grabmal gekommen sind."},
    [91860] = {n="Ein grausiges Schicksal", d="Untersucht die Insel Fenris im Osten, um vom Schicksal der Reisenden des Irdenen Rings zu erfahren.", objs={"Verkohlte Überreste"}},
    [91861] = {n="In die Burg Fenris", d="Untersucht Burg Fenris im Norden und versucht, das vermisste Mitglied der Gruppe des Irdenen Rings zu finden."},
    [91862] = {n="Lumina Windsinger", d="Beschafft den Schlüssel zur Insel Fenris von den Moderfellgnollen und verwendet ihn, um Lumina Windsinger zu befreien.", tgo={{"Wilder der Moderfelle", "Tobendes Moderfell", "Haudrauf der Moderfelle"}}},
    [91920] = {n="Wilde Augen", d="Sammelt 3 Murlocaugen und bringt sie zu Apotheker Renferrel am Grabmal.", tgo={{"Gobbler", "Räuber der Blaukiemen", "Murlocgezeitenjäger"}}},
    [91921] = {n="(Erneute) Rückkehr zu Quinn", d="Bringt Quinn Yorick auf dem Ivar-Feld, nördlich des Grabmals, Quinns Trank."},
    [92069] = {n="Reißende Klauen, durchbohrende Hauer", d="Bringt die Klauen des großen Bären und die Hauer des Ungebrochenen zu Ogtinc in Azshara."},
    [92343] = {n="Die Wurzel des Problems", d="Sammelt in der Schwarzschlundfeste 10 Wurzelspitzen von Nordrassil für Nara Wildmane in Thunder Bluff."},
    [92346] = {n="Unter Nordrassil", d="Sprecht mit Nara Wildmane auf der Anhöhe der Ältesten in Thunder Bluff."},
    [92401] = {n="Eine verängstigte Bitte", d="Untersucht das Verschwinden von Edward Heartweaver in den Ruinen von Lordaeron."},
    [92421] = {n="Die Gerechtigkeit des Lichts", d="Sammelt 25 intakte Gliedmaßen in den Ruinen von Lordaeron für Morbin Lightbane in Undercity."},
    [92422] = {n="Der Zorn von Rath'mael", d="Tötet Rath'mael in den Ruinen von Lordaeron für Todeswache Kristof in Brill."},
    [92434] = {n="Blut in den Straßen", d="Findet entlang des Lordameresees einen Weg nach Dalaran."},
    [92460] = {n="Erwachsen werden", d="Sprecht mit Rorian dem Tagsucher im Thendalhain."},
    [92461] = {n="Harmonisches Gleichgewicht", d="Tötet 8 junge Vuldren im Thendalhain.", tgo={{"Junger Vuldren"}}},
    [92462] = {n="Befallsbegutachtung", d="Tötet 8 lästige Zirrusfliegen im Thendalhain.", tgo={{"Lästige Zirrusfliege"}}},
    [92463] = {n="Die Zirrusfliegenkönigin", d="Vernichtet die Zirrusfliegenkönigin im Thendalhain.", tgo={{"Zirrusfliegenkönigin"}}},
    [92464] = {n="Unruhige Elemente", d="Sprecht mit Yala Windwächter im Thendalhain."},
    [92465] = {n="Aufrührer", d="Tötet 6 aufgewühlte Winde und 7 Konvertiten der Al'Aketh im Thendalhain.", tgo={{"Konvertit der Al'Aketh"}, {"Aufgewühlte Winde"}}},
    [92466] = {n="Ruf der Erde", d="Bringt Windformer Boro ein Siegel von Akir.", tgo={{"Schläger der Al'Aketh", "Konvertit der Al'Aketh", "Neophyt der Al'Aketh"}}},
    [92467] = {n="Ruf der Erde", d="Sucht die Anhöhe der Geister und trinkt das Erdsapta."},
    [92468] = {n="Ruf der Erde", d="Bringt den Rohquarz zu Windformer Boro im Thendalhain."},
    [92469] = {n="Rückkehr zu Rorian", d="Berichtet Rorian dem Tagsucher im Thendalhain von den Al'Aketh."},
    [92470] = {n="Widerwärtige Matriarchin", d="Tötet 8 Urseraplünderer und beschafft den Kopf ihrer Höhlenmutter Urs'anah im Thendalhain.", tgo={{"Urseraplünderer"}, {"Urs'anah"}}},
    [92471] = {n="Aetheen von den Winden", d="Sprecht mit Aetheen von den Winden im Thendalhain."},
    [92472] = {n="Der nächste Schritt", d="Meldet Euch bei Wachtmeisterin Aonda in Shen'dar."},
