    [95036] = {n="Eine mondgeküsste Klinge", d="Sprecht mit Trevan Rol im Grabmal und bringt ihm die Materialien, die er benötigt.", tgo={{"Trevan Rol"}, {}, {"Goblin-Holzschnitzer"}, {}, {}}},
    [95042] = {n="Suche nach dem Kor-Edelstein", d="Bringt einen Koredelstein zu Ulric Frostveil in Ashenvale.", tgo={{"Blackfathom-Gezeitenpriesterin", "Blackfathom-Orakel", "Blackfathom-Meerhexe"}}},
    [95111] = {n="Ein unterschätztes Talent", d="Sprecht mit Ott und bittet ihn, Eure Klinge zu schmieden."},
    [95118] = {n="Brackwasserbarbaren", d="Tötet 8 Murlocorakel und 8 Murlockrieger an der Ostwindküste.", tgo={{"Murlockrieger"}, {"Murlocorakel"}}},
    [95119] = {n="Feindschaftlicher Wettbewerb", d="Tötet 10 Bukaniere der östlichen See und 10 Musketiere der östlichen See an der Ostwindküste, nördlich vom Hafen von Powderfuse.", tgo={{"Bukanierin der östlichen See"}, {"Musketierin der östlichen See"}}},
    [95121] = {n="Schmeckt nach Meer", d="Sammelt 12 Murlocaugen und 6 Stück Sandkriecherfleisch für Fimbo Greasemitz.", tgo={{"Murlocorakel", "Murlocgezeitenläufer", "Murlockrieger"}, {"Sandkriecher", "Küstenkriecher"}}},
    [95122] = {n="Ungezügelte Expansion", d="Tötet 8 Räuber der östlichen See und 8 Bombenschützen der östlichen See für Werftmeister Whizzbuzz.", tgo={{"Räuberin der östlichen See"}, {"Bombenschütze der östlichen See"}}},
    [95123] = {n="Schickt sie zu den Haien!", d="Stehlt 5 Pulverfässchen der östlichen See für Werftmeister Whizzbuzz."},
    [95125] = {n="Otts Meisterwerk", d="Seht zu, während Ott Eure Klinge schmiedet.", tgo={{"Ott"}}},
    [95126] = {n="Die Mondsilberklinge", d="Bringt Otts Meisterwerk zu Trevan Rol im Silberwald.", star={"Mondsilberklinge", {"PALADIN"}}},
    [95140] = {n="Feuerauge der Alte", d="Verwendet die Mondsilberklinge, um Feuerauge den Alten im Silberwald zu vernichten.", tgo={{"Feuerauge der Alte"}, {}}, star={"Wolfsbann", {"PALADIN"}}},
    [95141] = {n="Berichtet in Rog'mar", d="Meldet Euch bei Krom'rosh am Außenposten Rog'mar in den Flusslanden."},
    [95143] = {n="Auf der Suche nach Tan'jani", d="Findet Tan'jani in Rog'mar in den Flusslanden."},
    [95162] = {n="Bleichhauerernte", d="Sammelt 10 Brocken Eberfleisch für Na'zok in der Nähe von Bolder'ok.", tgo={{"Steinhauereber", "Langschnauze", "Geiferzahn"}}},
    [95163] = {n="Drängt sie zurück", d="Bringt 10 junge Bleichhauer zurück zu Na'zoks Hof in der Nähe von Bolder'ok.", tgo={{"Junger Bleichhauer"}}},
    [95165] = {n="Schönen Flug, Ihr Salzwasserhalunken!", d="Platziert eine ferngezündete Sprengladung auf jedem der drei Schiffe der Piraten der östlichen See."},
    [95183] = {n="Schritt eins: Stein", d="Sammelt 10 gute Steine für Hamur in Bolder'ok.", objs={"Rock Pile"}},
    [95204] = {n="Wappen von Lordaeron", d="Bringt das Wappen von Lordaeron zu Oran Snakewrithe in Undercity."},
    [95216] = {n="Die neue Seuche", d="Bergt den hochgiftigen Erreger von Welkzahn in den Ruinen von Lordaeron für Theodore Griffs in Undercity."},
    [95254] = {n="GESUCHT: Fallenklaue", d="Bringt Fallenklaues Zange zu Fimbo Greasemitz.", tgo={{"Fallenklaue"}}},
    [95260] = {n="Schrecken der Tiefe", d="Findet jemanden am Hafen von Powderfuse, der das Ungeheuer auf dem bemalten Balg identifizieren kann."},
    [95261] = {n="Die inneren Werte", d="Sammelt 15 Bestieninnereien und 8 Faulfleischpilze für Argo Brinewhistle.", tgo={{"Ausgewachsener Bleichhauer", "Sandkriecher", "Küstenkriecher"}, {}}},
    [95267] = {n="Das Ungeheuer taucht auf", d="Verwendet den riesigen Köderballen, um das Meeresungeheuer hervorzulocken. Bringt dann seinen Kopf zu Argo Brinewhistle.", tgo={{"Monströser Dreschadon"}}},
    [95278] = {n="Es ist Zeit, Bruder...", d="Überbringt das Schreiben Krom'rosh in Rog'mar."},
    [95283] = {n="Die vermissten Kor'kron", d="Sprecht mit Nazeer Bloodpike in Brackenwall."},
    [95284] = {n="Die Elite der Elite", d="Findet die vermissten Elitesoldaten der Kor'kron."},
    [95285] = {n="Zur falschen Zeit am rechten Ort", d="Sprecht mit Sergeant Ulka, um mehr über die Lage auf der Insel Alcaz zu erfahren."},
    [95288] = {n="Schmugglerparadies", d="Sammelt 8 Schmuggelwaren für Friz Frazzlespark im Hafen von Powderfuse.", tgo={{"Bukanierin der östlichen See", "Musketierin der östlichen See"}}},
    [95293] = {n="Schmugglerspezialität", d="Bringt das Friz-Special zu Captain Bentcoin an der Ostwindküste."},
    [95309] = {n="Kein Orc bleibt zurück", d="Begebt Euch in das Gefängnis von Alcaz und findet Kommandant Folkar."},
    [95349] = {n="Der Irdene Ring", d="Nehmt das Himmelsseglerschiff von der Insel Zephras nach Mulgore und sprecht mit Alaana Stormwalker, wenn Ihr ankommt."},
    [95350] = {n="Willkommen in Azeroth", d="Reist nach Orgrimmar und sprecht mit Thrall im Tal der Weisheit."},
    [95417] = {n="Die Lilanen", d="Findet vermisste Oger in den Höhlen unter Sonnengrund für Clubtoe."},
    [95418] = {n="Weitersagen", d="Bringt Choggs Kopf zu Tran'gul in Rog'mar."},
    [95420] = {n="Land der Riesen", d="Bringt Chogg'zacs Kopf in die Ogerstadt im Norden."},
    [95424] = {n="Macht gibt recht", d="Tötet 7 Twilight-Zermalmer und 7 Twilight-Feuerrufer für Clugfist in Bolder'ok.", tgo={{"Twilight-Zermalmer"}, {"Twilight-Feuerrufer"}}},
    [95425] = {n="Unwürdiger Champion", d="Holt den Schädelbrecher von Klunk und Clugfist in Bolder'ok.", tgo={{"Klunk"}}},
    [95427] = {n="Nie mehr Twilight-Hammer!", d="Tötet Chogg'Zac in der Sonnengrundhöhle und sammelt ihre Köpfe für Clubtoe.", tgo={{"Chogg'Zac"}, {"Chogg'Zac"}}},
