    [95773] = {n="Feinde im Wasser", d="Sammelt 10 Laugenschuppendreizacke von Scharmützlern der Laugenschuppen.", tgo={{"Scharmützler der Laugenschuppen"}}},
    [95774] = {n="Ihr Name ist Olgra", d="Erschlagt Stacheleber und sammelt 4 von Olgras Schmuckstücken für Mankriks Denkmal.", tgo={{"Räuber der Grimmhauer"}}},
