    [95928] = {n="Kristalline Elemente", d="Bringt Mayena Earthseeker einen feuchten Kristall, einen aufgeladenen Kristall, einen giftigen Kristall und einen feurigen Kristall von der Terrasse des Formers."},
    [95951] = {n="Schnitzen und Stibitzen", d="Sammelt Holzbündel von Arbeiterholzstapeln in Turners Holzfällerlager und schnitzt 20 behelfsmäßige Stechspeere daraus."},
    [95955] = {n="Stecht sie", d="Durchbohrt 10 Süßwasserkrokilisken und kehrt zu Tan'jani in Rog'mar zurück.", tgo={{"Süßwasserkrokilisk"}}},
    [95981] = {n="Straßensperre", d="Tötet 8 Hexer von Dalaran und 8 Behüter von Dalaran für Schattenpriester Allister am Grabmal.", tgo={{"Behüter von Dalaran"}, {"Hexer von Dalaran"}}},
